/** The step a fresh canvas starts with. */
export const PLACEHOLDER = 'placeholder';

/** The outputs a step has: [{ id, label }]. */
export function outputsOf(data: StepData): Output[] {
  const a = ACTIONS[data.action];
  if (data.action === PLACEHOLDER) return [{ id: 'out', label: '' }];
  if (!a) return [];
  if (a.kind === 'condition') return [{ id: 'true', label: 'true' }, { id: 'false', label: 'false' }];
  if (a.kind === 'switch') return (data.outputs || []).map((o) => ({ id: o.id, label: o.label, rule: o.rule }));
  return [{ id: 'out', label: '' }];
}

/** A fresh step's data for an action key. */
export function newStepData(action: string, overrides: { props?: Props; outputs?: Output[] } = {}): StepData {
  const a = ACTIONS[action];
  const data: StepData = { action, props: { ...a.defaults(), ...(overrides.props || {}) } };
  if (a.outputs) data.outputs = overrides.outputs || a.outputs();
  return data;
}

/** The first empty required field, or null. */
export function missingField(data: StepData): Field | null {
  const a = ACTIONS[data.action];
  if (!a) return null;
  for (const f of a.fields) if (f.required && String(data.props[f.key] ?? '').trim() === '') return f;
  return null;
}

/** The sample: a GitLab push that deploys, checks health and responds. */
export function sampleWorkflow(): WorkflowDoc {
  const s = (id: string, action: string, props: Props, extra?: { outputs?: Output[] }): DocStep => ({ id, x: 0, y: 0, data: newStepData(action, { props, ...(extra || {}) }) });
  const steps = [
    s('push', 'gitlab.push', { project: 'storefront/checkout-api', branch: 'main', event: 'Push' }),
    s('cond', 'logic.condition', { field: 'message', operator: 'contains', value: 'release' }),
    s('stage', 'k8s.deploy', { cluster: 'eks-staging-eu', namespace: 'checkout', environment: 'staging', strategy: 'Rolling update' }),
    s('health', 'logic.switch', { name: 'Health check' }),
    s('prod', 'k8s.deploy', { cluster: 'eks-prod-eu', namespace: 'checkout', environment: 'production', strategy: 'Canary' }),
    s('dd_prod', 'datadog.event', { title: 'Release live in production', tags: 'service:checkout,env:prod' }),
    s('slack_rel', 'slack.message', { channel: '#releases', message: 'checkout-api is live in production' }),
    s('pd_slow', 'pagerduty.incident', { service: 'checkout-api', severity: 'warning', title: 'Checkout running slow' }),
    s('jira_slow', 'jira.transition', { project: 'REL', issue: 'Release ticket', transition: 'Investigate' }),
    s('rollback', 'k8s.rollback', { cluster: 'eks-staging-eu', namespace: 'checkout', revision: 'previous' }),
    s('pd_down', 'pagerduty.incident', { service: 'checkout-api', severity: 'critical', title: 'Release failed health check' }),
    s('snow', 'servicenow.incident', { group: 'Platform Ops', impact: '1 - High', title: 'Checkout release rolled back' }),
    s('cw', 'cloudwatch.alarm', { alarm: 'Missing health signal', metric: 'HealthCheckStatus' }),
    s('jira_ops', 'jira.create', { project: 'OPS', type: 'Task', title: 'Health check sent no data' }),
    s('dev', 'k8s.deploy', { cluster: 'gke-dev-us', namespace: 'checkout', environment: 'development', strategy: 'Rolling update' }),
    s('dd_dev', 'datadog.event', { title: 'Dev build deployed', tags: 'service:checkout,env:dev' }),
  ];
  const L = (n: number, s0: string, out: string, t: string): DocLink => ({ id: 'l' + n, s: `${s0}__${out}`, t: `${t}__in` });
  const links = [
    L(1, 'push', 'out', 'cond'),
    L(2, 'cond', 'true', 'stage'), L(3, 'cond', 'false', 'dev'),
    L(4, 'stage', 'out', 'health'),
    L(5, 'health', 'o_healthy', 'prod'), L(6, 'prod', 'out', 'dd_prod'), L(7, 'dd_prod', 'out', 'slack_rel'),
    L(8, 'health', 'o_degraded', 'pd_slow'), L(9, 'pd_slow', 'out', 'jira_slow'),
    L(10, 'health', 'o_failed', 'rollback'), L(11, 'rollback', 'out', 'pd_down'), L(12, 'pd_down', 'out', 'snow'),
    L(13, 'health', 'o_else', 'cw'), L(14, 'cw', 'out', 'jira_ops'),
    L(15, 'dev', 'out', 'dd_dev'),
  ];
  const notes = [{
    id: 'note_health',
    title: 'After the health check',
    text: 'The Switch reads how the staging rollout is doing and runs exactly one response:\n'
      + '• healthy: promote to production and tell the team\n'
      + '• degraded or failed: page on-call and track it in a ticket\n'
      + '• no data: raise an alarm instead of guessing',
    members: ['prod', 'dd_prod', 'slack_rel', 'pd_slow', 'jira_slow', 'rollback', 'pd_down', 'snow', 'cw', 'jira_ops'],
  }];
  return { v: 1, title: 'Checkout release pipeline', steps, links, notes };
}

// The workflow builder's behaviour — translated line for line from the setup()
// of demos/interaction/workflow-builder.html. It owns the engine side (painting
// a step from its data, the page's undo steps, the sticky-note layer, the tidy
// re-arrangement, the "+" buttons and the pointer, Save / Load / New), with
// five parts beside it: the sticky-note layer (workflow-builder-notes.ts), the
// panel as data (-panel.ts), the add-step menu (-menu.ts), Test workflow
// (-run.ts) and the navigator card (-navigator.ts). The framework component owns the markup — the top bar, the
// property panel, the menu, the run card, the navigator card, the toast —
// reads this controller's public fields, and re-renders when it calls
// onUpdate(). Framework-free: the same file sits next to the workflow-builder
// demo in the React, Vue, Angular and Qwik apps.
//
// The library workarounds the JS page carries, carried here too:
//   • icons are page-CSS classes with data-URI backgrounds (HTML node content
//     strips <svg> and url(): see workflow-builder-icons.ts);
//   • a CAPTURING window keydown, armed BEFORE the canvas mounts (armKeys()),
//     owns Delete, so the engine's own Delete never skips the chain-healing;
//   • the tidy layout is one undo step: a DocCommand whose first execute() is
//     a no-op (the model already shows the edit);
//   • notes are drawn on a div UNDER the SVG that copies
//     viewport.getHtmlLayerTransform();
//   • a note keeps its frame while a step is dragged (the engine decides on
//     drop, by that frame, whether the step left or joined it).
import { NodeModel, LinkModel, PortModel, GroupModel, Command, DiagramSerializer } from '@grafloria/engine';
import { iconCss } from './workflow-builder-icons';
import { ACTIONS, PLACEHOLDER, outputsOf, newStepData, sampleWorkflow, type StepData, type WorkflowDoc } from './workflow-builder-catalog';
import { layoutFlow, visualBox } from './workflow-builder-layout';
import {
  TILE, kindOf, portIdOf, geomOf, stepContent, portList, portConfig, DARK, lineStyle, type PortSpec,
} from './workflow-builder-steps';
import { panelView, selectionExists, type PanelView, type Sel } from './workflow-builder-panel';
import { StepMenu } from './workflow-builder-menu';
import { TestRun, type RunHost } from './workflow-builder-run';
import { Navigator } from './workflow-builder-navigator';
import { NoteLayer } from './workflow-builder-notes';

interface MenuCtx { mode: 'insert' | 'branch' | 'trigger'; port?: string; nodeId?: string; world?: { x: number; y: number } | null }

const portModel = (p: PortSpec) => new PortModel({ ...portConfig(p), isConnectableStart: p.type === 'output', isConnectableEnd: p.type === 'input',
  allowSelfLink: false, allowDuplicateLinks: false } as any);

const FRAME_STYLE = { fill: 'none', stroke: 'none', color: 'transparent', labelPlacement: 'top-left' };
const clone = <T>(v: T): T => JSON.parse(JSON.stringify(v));
const newId = () => 's' + Date.now().toString(36).slice(-5) + Math.floor(Math.random() * 1296).toString(36);
const isTextEntry = (t: any) => !!t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName || ''));
const sameDoc = (a: WorkflowDoc, b: WorkflowDoc) => JSON.stringify(a) === JSON.stringify(b);
const KEY = 'grafloria-demo-workflow-builder';
const ICON_STYLE_ID = 'wf-icon-css';
/** One undo step for a page edit: the workflow before and after. */
class DocCommand extends Command {
  before: WorkflowDoc;
  after: WorkflowDoc;
  apply: (doc: WorkflowDoc) => void;
  fresh: boolean;
  constructor(name: string, before: WorkflowDoc, after: WorkflowDoc, apply: (doc: WorkflowDoc) => void) {
    super(name); this.before = before; this.after = after; this.apply = apply; this.fresh = true;
  }
  execute() { if (this.fresh) { this.fresh = false; return; } this.apply(this.after); }
  undo() { this.apply(this.before); }
  redo() { this.apply(this.after); }
  serialize() { return { id: this.id, name: this.name, timestamp: this.timestamp, data: { before: this.before, after: this.after } }; }
}

export class WorkflowBuilderController {
  // ---- what the templates read ---------------------------------------------------
  title = '';
  stateText = 'Not saved yet';
  dirty = false;
  canUndo = false;
  canRedo = false;
  /** The add-step menu: its search, its sections, its highlight, its place. */
  readonly menu = new StepMenu();
  /** Test workflow: the run card's state, and the walk itself. */
  readonly test = new TestRun(this.runHost());
  /** The navigator card: minimap, zoom slider, Fit, Fit width. */
  readonly nav = new Navigator(() => this.changed());
  // the toast
  toastText = '';
  toastOn = false;
  /** The tidy re-arrangement's duration (ms). */
  animMs = 380;
  /** The step the last "+" / menu pick added. */
  lastInserted: string | null = null;

  /** Re-render the component; set by the framework. */
  onUpdate: () => void = () => {};
  /** Bumped on every change: the panel view is recomputed once per version. */
  ver = 0;

  /** The right-hand panel as data (recomputed once per change). */
  get panel(): PanelView {
    if (!this.panelCache || this.panelVer !== this.ver) { this.panelCache = panelView(this.model, this.sel, this.typed); this.panelVer = this.ver; }
    return this.panelCache;
  }
  /** Narrow stages slide the panel away while nothing is selected. */
  get panelIdle(): boolean { return !this.sel || !selectionExists(this.model, this.sel); }

  // ---- engine side -------------------------------------------------------------------
  private api: any = null;
  private model: any = null;
  private engine: any = null;
  private cm: any = null;
  private root!: HTMLElement;        // #stage
  private host!: HTMLElement;        // #canvas: the flow and its chrome
  private offs: Array<() => void> = [];
  private keyOff: (() => void) | null = null;
  private keysReady = false;
  private sel: Sel = null;
  private editBefore: WorkflowDoc | null = null;
  private savedAt: number | null = null;
  /** What a number box shows while it is typed in (the step keeps the number). */
  private typed = new Map<string, string>();
  private panelCache: PanelView | null = null;
  private panelVer = -1;
  private toastTimer: ReturnType<typeof setTimeout> | undefined;
  private notes = new NoteLayer();
  private frameRaf = 0;
  private tween: { to: Map<string, { x: number; y: number }>; resolve: () => void; raf: number } | null = null;
  private layoutDone: Promise<void> = Promise.resolve();
  private menuCtx: MenuCtx | null = null;
  private plusDown: string | null = null;
  private press: { x: number; y: number; w: { x: number; y: number }; onSomething: boolean } | null = null;
  private lastUp: { x: number; y: number; t: number } | null = null;
  private panJob = 0;

  private changed(): void { this.ver++; this.onUpdate(); }
  /** What Test workflow needs from the canvas. */
  private runHost(): RunHost {
    const c = this;
    return {
      get model() { return c.model; },
      paint: (id) => c.paint(id),
      reveal: (id) => c.reveal(id),
      renderNow: () => c.api?.renderNow(),
      miniRefresh: () => c.nav.refresh(),
      scrollLog: () => requestAnimationFrame(() => { const el = c.host?.querySelector('.rn-log'); if (el) el.scrollTop = el.scrollHeight; }),
      changed: () => c.changed(),
    };
  }

  // ---- keyboard: Delete through the page (one undo step, with re-arrangement) ------------
  /**
   * Arm the keyboard BEFORE the canvas mounts: a key event dispatched AT window
   * runs window's listeners in registration order, and the engine's own Delete
   * must not run first (it would skip the chain-healing and the re-arrangement).
   * Safe to call again.
   */
  armKeys(): void {
    if (this.keyOff) return;
    const onKey = (e: KeyboardEvent) => {
      if (!this.keysReady || isTextEntry(e.target)) return;
      if (e.key === 'Escape') { this.lastUp = null; if (this.menu.open) { this.closeMenu(); e.stopImmediatePropagation(); } return; }
      if (e.key !== 'Delete' && e.key !== 'Backspace') return;
      const model = this.model, sel = this.sel;
      const nodes = model.getSelectedNodes(), link = model.getLinks().find((l: any) => l.state === 'selected');
      if (sel?.type === 'note') this.deleteNote(sel.id);
      else if (nodes.length) this.deleteSteps(nodes.map((n: any) => n.id));
      else if (link) this.deleteLink(link.id);
      else return;
      e.preventDefault();
      e.stopImmediatePropagation();
    };
    window.addEventListener('keydown', onKey, true);
    this.keyOff = () => window.removeEventListener('keydown', onKey, true);
  }

  /** Mount on a fresh instance: `root` is #stage (top bar, #canvas, #panel). Safe to call again. */
  init(instance: any, root: HTMLElement): void {
    this.teardown();
    this.armKeys();
    const api = (this.api = instance);
    const model = (this.model = instance.getModel());
    const engine = (this.engine = instance.getEngine());
    this.cm = engine.commandManager;
    this.root = root;
    this.host = root.querySelector('#canvas') as HTMLElement;
    const host = this.host;
    api.animations?.updateConfig?.({ respectBatteryStatus: false, batterySavingMode: false });
    // Labels and "+" buttons stay drawn at every zoom: widen every LOD tier.
    try {
      const cfg = model.getLODConfig(), all = new Set<unknown>();
      for (const t of cfg.tiers) for (const f of t.features) all.add(f);
      for (const t of cfg.tiers) for (const f of all) t.features.add(f);
      model.setLODConfig(cfg);
    } catch { /* an engine without LOD config draws everything anyway */ }

    // The icons: one stylesheet of data-URI classes in <head>.
    if (!document.getElementById(ICON_STYLE_ID)) {
      const st = document.createElement('style');
      st.id = ICON_STYLE_ID;
      st.textContent = iconCss();
      document.head.appendChild(st);
    }
    // ---- chrome over the canvas keeps its pointer, wheel and double-click -------
    const stop = (e: Event) => e.stopPropagation();
    for (const el of Array.from(host.querySelectorAll('.wf-menu, .wf-run, .wf-nav'))) {
      for (const t of ['pointerdown', 'mousedown', 'wheel', 'dblclick']) {
        el.addEventListener(t, stop);
        this.offs.push(() => el.removeEventListener(t, stop));
      }
    }

    this.sel = null; this.editBefore = null; this.typed.clear();
    this.test.clear();
    this.menu.open = false; this.menuCtx = null;

    for (const ev of ['command:executed', 'command:undone', 'command:redone', 'command:history:cleared']) {
      this.offs.push(engine.eventBus.on(ev, (p: any) => {
        this.syncHistory();
        if (ev === 'command:history:cleared') return;
        this.markDirty();
        const native = !(p?.command instanceof DocCommand);
        if (native) this.scheduleFrames();
        // An undo/redo, or an engine gesture (reconnect, membership) the panel shows.
        if (ev !== 'command:executed' || (native && this.sel?.type !== 'step')) this.renderPanel();
      }));
    }

    // ---- sticky notes: the layer under the diagram ------------------------------
    this.notes.mount(api, host.querySelector('.grafloria-diagram-root') as HTMLElement);
    const frames = () => this.scheduleFrames();
    for (const ev of ['node:changed', 'group:changed', 'node:removed', 'link:added', 'link:removed']) this.offs.push(model.on(ev, frames));
    this.offs.push(api.on('viewport:change', ({ zoom }: { zoom: number }) => {
      this.notes.follow();
      this.nav.zoomed(zoom);
    }));

    // ---- selection ----------------------------------------------------------------
    this.offs.push(api.on('selection:change', ({ nodes, edges }: any) => {
      if (nodes.length === 1) {
        this.setSel({ type: 'step', id: nodes[0].id });
        if (nodes[0].data?.action === PLACEHOLDER) this.openMenuAtStep(nodes[0].id, { mode: 'trigger', nodeId: nodes[0].id });
      } else if (nodes.length > 1) this.setSel({ type: 'multi', ids: nodes.map((n: any) => n.id) });
      else if (edges.length === 1) this.setSel({ type: 'link', id: edges[0].id });
      else if (this.sel?.type !== 'note') this.setSel(null);
    }));

    // An edit is committed (one undo step) when its field fires `change`, as on
    // the JS page. Listened to natively: React's onChange is the INPUT event.
    const onChange = (e: Event) => {
      const t = e.target as HTMLElement;
      if (t.id === 'wf-title') this.commitEdit('Rename');
      else if (t.closest?.('#panel')) this.commitEdit('Edit properties');
    };
    root.addEventListener('change', onChange);
    this.offs.push(() => root.removeEventListener('change', onChange));

    // A line someone drew by hand: style it like the others.
    this.offs.push(api.on('connect', ({ link }: any) => setTimeout(() => {
      if (model.getLink(link.id) && !this.test.running) { link.pathType = 'bezier'; link.updateStyle(lineStyle()); }
      api.renderNow();
    }, 0)));

    // The add-step menu closes on a press anywhere outside it.
    const onDocDown = (e: PointerEvent) => {
      const menu = host.querySelector('#wf-menu'), t = e.target as Element;
      if (this.menu.open && menu && !menu.contains(t) && !t.closest?.('[data-act="add-after"]')) this.closeMenu();
    };
    document.addEventListener('pointerdown', onDocDown, true);
    this.offs.push(() => document.removeEventListener('pointerdown', onDocDown, true));

    // ---- pointer: the "+" buttons, note clicks, a line let go on empty canvas ---------------
    const toWorld = (cx: number, cy: number) => api.viewport.clientToWorld(cx, cy, host.getBoundingClientRect());
    const plusPort = (el: any): string | null => [...(el?.closest?.('.wf-plus')?.classList ?? [])].find((c: string) => c.startsWith('wfp-'))?.slice(4) ?? null;
    const onDown = (e: PointerEvent) => {
      this.settle();
      const pid = plusPort(e.target);
      if (pid) { e.stopPropagation(); e.preventDefault(); this.plusDown = pid; return; }
      const w = toWorld(e.clientX, e.clientY);
      const onSomething = !!model.getNodeAtPosition(w.x, w.y) || !!api.interaction.getState().hoveredPort
        || !!api.interaction.getLinkAtPosition(w.x, w.y, engine) || !!(e.target as Element).closest?.('.wf-label, [data-node-id] foreignObject *');
      this.press = { x: e.clientX, y: e.clientY, w, onSomething };
    };
    const onMouse = (e: Event) => { if (plusPort(e.target)) e.stopPropagation(); };
    host.addEventListener('pointerdown', onDown, true);
    host.addEventListener('mousedown', onMouse, true);
    host.addEventListener('click', onMouse, true);
    const onUp = (e: PointerEvent) => {
      this.lastUp = { x: e.clientX, y: e.clientY, t: performance.now() };
      const pid = this.plusDown && plusPort(document.elementFromPoint(e.clientX, e.clientY) || e.target) === this.plusDown ? this.plusDown : null;
      this.plusDown = null;
      if (pid) {
        e.stopPropagation();
        const r = document.querySelector(`.wfp-${CSS.escape(pid)}`)?.getBoundingClientRect();
        this.openMenu((r?.right ?? e.clientX) + 6, (r?.top ?? e.clientY) - 12, { mode: 'insert', port: pid });
        return;
      }
      const p = this.press;
      this.press = null;
      if (!p || p.onSomething || Math.hypot(e.clientX - p.x, e.clientY - p.y) > 4 || !host.contains(e.target as Node)) return;
      const note = model.getGroups().find((g: any) => {
        if (!g.getMetadata('note')) return false;
        const f = g.getOuterBounds();
        return p.w.x >= f.x && p.w.x <= f.x + f.width && p.w.y >= f.y && p.w.y <= f.y + f.height;
      });
      if (note) this.selectNote(note.id);
      else if (this.sel?.type === 'note') this.setSel(null);
    };
    window.addEventListener('pointerup', onUp, true);
    this.offs.push(() => {
      host.removeEventListener('pointerdown', onDown, true);
      host.removeEventListener('mousedown', onMouse, true);
      host.removeEventListener('click', onMouse, true);
      window.removeEventListener('pointerup', onUp, true);
    });
    this.offs.push(engine.eventBus.on('connection:cancel', (p: any) => setTimeout(() => {
      const src = p?.sourcePort?.id, lastUp = this.lastUp;
      if (!src || !lastUp || performance.now() - lastUp.t > 400 || !src.includes('__') || src.endsWith('__in')) return;
      const w = toWorld(lastUp.x, lastUp.y);
      const r = host.getBoundingClientRect();
      if (lastUp.x < r.left || lastUp.x > r.right || lastUp.y < r.top || lastUp.y > r.bottom) return;
      const over = model.getNodes().filter((n: any) => { const b = visualBox(this.boxOf(n)); return w.x >= b.x0 && w.x <= b.x1 && w.y >= b.y0 && w.y <= b.y1; }).pop();
      const fromNode = model.getNodeByPortId(src);
      if (over && over !== fromNode && over.getPort(`${over.id}__in`)) {
        if (!model.getLinks().some((l: any) => l.sourcePortId === src && l.targetPortId === `${over.id}__in`)) {
          void engine.addLink({ sourcePortId: src, targetPortId: `${over.id}__in`, type: 'bezier' }).then((l: any) => { l?.updateStyle?.(lineStyle()); api.renderNow(); }).catch(() => {});
        }
        return;
      }
      if (!over) this.openMenu(lastUp.x + 6, lastUp.y - 12, { mode: 'branch', port: src, world: { x: w.x, y: w.y - 28 } });
    }, 0)));

    // ---- navigator: the minimap ------------------------------------------------------
    this.nav.mount(api, host, host.querySelector('#wf-mm') as HTMLElement, this.test.status);
    const onDark = () => { for (const l of model.getLinks()) if (!this.test.status.size) l.updateStyle(lineStyle()); this.nav.refresh(); api.renderNow(); };
    DARK.addEventListener?.('change', onDark);
    this.offs.push(() => DARK.removeEventListener?.('change', onDark));

    this.keysReady = true;
    this.reset();
  }

  /** Unmount: listeners off, runs and animations stopped, the measuring twin and the icon sheet removed. */
  destroy(): void {
    this.teardown();
    this.keyOff?.();
    this.keyOff = null;
    this.notes.dispose();
    document.getElementById(ICON_STYLE_ID)?.remove();
  }

  private teardown(): void {
    this.keysReady = false;
    for (const off of this.offs.splice(0)) { try { off(); } catch { /* already gone */ } }
    if (this.tween) { cancelAnimationFrame(this.tween.raf); this.tween = null; }
    this.test.clear();
    this.panJob++;
    clearTimeout(this.toastTimer);
    cancelAnimationFrame(this.frameRaf); this.frameRaf = 0;
    this.nav.dispose();
    this.notes.unmount();
  }

  toast(text: string): void {
    this.toastText = text; this.toastOn = true;
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => { this.toastOn = false; this.changed(); }, 2600);
    this.changed();
  }

  // ---- painting a step: content, size and ports follow node.data ----------------
  private paint(id: string): void {
    const model = this.model, node = model.getNode(id);
    if (!node || !node.data?.action) return;
    const data = node.data, g = geomOf(data);
    const sel = this.sel;
    node.setMetadata('html', { content: stepContent(id, data, { sel: sel?.type === 'step' && sel.id === id, status: this.test.status.get(id) }), padding: 0, style: { overflow: 'visible' } });
    if (node.size.width !== g.w || node.size.height !== g.h) node.setSize(g.w, g.h);
    const want = portList(id, data), keep = new Set(want.map((p) => p.id));
    for (const port of [...node.getPorts()]) {
      if (keep.has(port.id)) continue;
      for (const l of model.getLinks()) if (l.sourcePortId === port.id || l.targetPortId === port.id) model.removeLink(l.id);
      node.removePort(port.id);
    }
    for (const p of want) {
      const have = node.getPort(p.id), a = have?.layout?.args;
      if (have && a && a.x === p.x && a.y === p.y) continue;
      if (have) node.removePort(p.id);   // re-seat under the SAME id: its lines stay on it
      node.addPort(portModel(p));
    }
  }
  private paintAll(): void { for (const n of this.model.getNodes()) this.paint(n.id); }
  private buildNode(step: { id: string; x: number; y: number; data: StepData }): any {
    const g = geomOf(step.data);
    const node: any = new NodeModel({ id: step.id, type: 'rect', position: { x: step.x, y: step.y }, size: { width: g.w, height: g.h } } as any);
    node.ports.clear();
    node.data = clone(step.data);
    node.setMetadata('shape', { type: 'rect' });
    node.behavior.resizable = false;
    node.style = { ...node.style, selection: 'border' };
    return node;
  }
  private addLink(id: string, s: string, t: string): any {
    const model = this.model, src = model.getNodeByPortId(s), tgt = model.getNodeByPortId(t);
    if (!src || !tgt) return null;
    const l: any = new LinkModel(s, t, 'bezier' as any);
    l.id = id;
    l.sourceNodeId = src.id; l.targetNodeId = tgt.id;
    l.updateStyle(lineStyle());
    model.addLink(l);
    return l;
  }

  // ---- the document: the workflow as plain data ---------------------------------
  private docOf(m: any, title: string): WorkflowDoc {
    return {
      v: 1, title,
      steps: m.getNodes().filter((n: any) => n.data?.action).map((n: any) => ({ id: n.id, x: Math.round(n.position.x), y: Math.round(n.position.y), data: clone(n.data) })),
      links: m.getLinks().map((l: any) => ({ id: l.id, s: l.sourcePortId, t: l.targetPortId })),
      notes: m.getGroups().filter((g: any) => g.getMetadata('note')).map((g: any) => ({ id: g.id, ...clone(g.getMetadata('note')),
        members: [...g.members].filter((id) => m.getNode(id)), frame: { ...g.getOuterBounds() } })),
    };
  }
  private docFromModel(): WorkflowDoc { return this.docOf(this.model, this.title); }

  private applyDoc(doc: WorkflowDoc): void {
    const model = this.model;
    this.cancelTween();
    this.test.stop(true);
    this.closeMenu();
    const wantLinks = new Map(doc.links.map((l) => [l.id, l]));
    for (const l of [...model.getLinks()]) {
      const w = wantLinks.get(l.id);
      if (!w || w.s !== l.sourcePortId || w.t !== l.targetPortId) model.removeLink(l.id);
    }
    const wantSteps = new Set(doc.steps.map((s) => s.id));
    for (const n of [...model.getNodes()]) if (!wantSteps.has(n.id)) model.removeNode(n.id);
    for (const s of doc.steps) {
      const node = model.getNode(s.id);
      if (!node) model.addNode(this.buildNode(s));
      else {
        node.data = clone(s.data);
        if (node.position.x !== s.x || node.position.y !== s.y) node.setPosition(s.x, s.y);
      }
      this.paint(s.id);
    }
    for (const l of doc.links) if (!model.getLink(l.id)) this.addLink(l.id, l.s, l.t);
    const wantNotes = new Map(doc.notes.map((n) => [n.id, n]));
    for (const g of [...model.getGroups()]) if (!wantNotes.has(g.id)) model.removeGroup(g.id);
    for (const nt of doc.notes) {
      let g = model.getGroup(nt.id);
      if (!g) {
        g = new GroupModel({ id: nt.id, name: nt.title } as any);
        g.headerHeight = 0;
        model.addGroup(g);
        g.setMetadata('frameStyle', { ...FRAME_STYLE });
      }
      g.name = nt.title;
      g.setMetadata('note', { title: nt.title, text: nt.text });
      for (const m of [...g.members]) if (!nt.members.includes(m as string)) g.removeMember(m, model);
      for (const m of nt.members) if (model.getNode(m) && !g.members.has(m)) g.addMember(m, model);
      if (nt.frame && !nt.members.length) g.setFrame(nt.frame);
    }
    this.title = doc.title ?? this.title;
    if (this.sel && !selectionExists(this.model, this.sel)) this.sel = null;
    this.typed.clear();
    this.refreshFrames();
    this.paintAll();
    this.api.renderNow();
    this.renderPanel();
    this.syncHistory();
  }

  private commit(name: string, before: WorkflowDoc, after: WorkflowDoc = this.docFromModel()): void {
    if (sameDoc(before, after)) return;
    void this.cm.execute(new DocCommand(name, before, after, (d) => this.applyDoc(d))).then(() => this.syncHistory());
    this.markDirty();
  }
  private markDirty(): void { this.dirty = true; this.stateText = 'Unsaved changes'; this.changed(); }
  private syncHistory(): void {
    const u = this.cm.canUndo(), r = this.cm.canRedo();
    if (u !== this.canUndo || r !== this.canRedo) { this.canUndo = u; this.canRedo = r; this.changed(); }
  }

  // ---- sticky notes (workflow-builder-notes.ts draws them) -------------------------
  private boxOf(node: any) { return { ...geomOf(node.data), x: node.position.x, y: node.position.y, id: node.id }; }
  private noteSel(): string | null { return this.sel?.type === 'note' ? this.sel.id : null; }
  private refreshFrames(): void { this.notes.fit(this.noteSel()); this.nav.refresh(); }
  private renderNotes(): void { this.notes.render(this.noteSel()); }
  private scheduleFrames(): void {
    if (this.frameRaf) return;
    this.frameRaf = requestAnimationFrame(() => { this.frameRaf = 0; this.refreshFrames(); });
  }

  // ---- the automatic left-to-right arrangement -----------------------------------
  private computeLayout(): Map<string, { x: number; y: number }> {
    const model = this.model;
    const nodes = model.getNodes().filter((n: any) => n.data?.action).map((n: any) => ({ ...this.boxOf(n), first: ['trigger', 'placeholder'].includes(kindOf(n.data)) }));
    const links = model.getLinks().map((l: any, i: number) => {
      const src = model.getNodeByPortId(l.sourcePortId);
      const outIdx = src?.data ? outputsOf(src.data).findIndex((o) => portIdOf(src.id, src.data, o) === l.sourcePortId) : 0;
      return { from: l.sourceNodeId, to: l.targetNodeId, order: Math.max(0, outIdx) * 1000 + i };
    });
    const notes = model.getGroups().filter((g: any) => g.getMetadata('note')).map((g: any) => ({ id: g.id, members: [...g.members] as string[], header: this.notes.header(g.getMetadata('note')) }));
    return layoutFlow({ nodes, links, notes }).pos;
  }
  private cancelTween(): void { if (!this.tween) return; cancelAnimationFrame(this.tween.raf); const t = this.tween; this.tween = null; t.resolve(); }
  private settle(): void {
    if (!this.tween) return;
    const t = this.tween;
    for (const [id, p] of t.to) this.model.getNode(id)?.setPosition(p.x, p.y);
    this.cancelTween();
    this.refreshFrames();
  }
  private animateTo(target: Map<string, { x: number; y: number }>): Promise<void> {
    this.cancelTween();
    const model = this.model;
    const from = new Map<string, { x: number; y: number }>(), to = new Map<string, { x: number; y: number }>();
    for (const [id, p] of target) {
      const n = model.getNode(id);
      if (!n) continue;
      from.set(id, { x: n.position.x, y: n.position.y });
      to.set(id, p);
    }
    const ms = matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : this.animMs;
    if (!ms) { for (const [id, p] of to) model.getNode(id).setPosition(p.x, p.y); this.refreshFrames(); this.api.renderNow(); return (this.layoutDone = Promise.resolve()); }
    this.layoutDone = new Promise<void>((resolve) => {
      const t0 = performance.now();
      this.tween = { to, resolve, raf: 0 };
      const step = (now: number) => {
        if (!this.tween || this.tween.to !== to) return;
        const k = Math.min(1, (now - t0) / ms), e = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
        for (const [id, p] of to) {
          const a = from.get(id)!, n = model.getNode(id);
          if (n) n.setPosition(Math.round(a.x + (p.x - a.x) * e), Math.round(a.y + (p.y - a.y) * e));
        }
        this.refreshFrames();
        if (k < 1) this.tween.raf = requestAnimationFrame(step);
        else { this.tween = null; resolve(); }
      };
      this.tween.raf = requestAnimationFrame(step);
    });
    return this.layoutDone;
  }
  /** Commit an edit already applied to the model, then slide the flow into its new arrangement. */
  private commitWithLayout(name: string, before: WorkflowDoc): Promise<void> {
    const target = this.computeLayout();
    const doc = this.docFromModel();
    this.commit(name, before, { ...doc, steps: doc.steps.map((s) => (target.has(s.id) ? { ...s, x: target.get(s.id)!.x, y: target.get(s.id)!.y } : s)) });
    return this.animateTo(target);
  }

  // ---- selection -----------------------------------------------------------------
  private setSel(next: Sel): void {
    const prev = this.sel;
    this.sel = next;
    this.typed.clear();
    if (prev?.type === 'step') this.paint(prev.id);
    if (next?.type === 'step') this.paint(next.id);
    this.renderNotes();
    this.api.renderNow();
    if (this.editBefore) { this.commit('Edit', this.editBefore); this.editBefore = null; }
    this.renderPanel();
  }
  private selectStep(id: string): void {
    const model = this.model;
    model.clearSelection();
    for (const l of model.getLinks()) if (l.state === 'selected') l.setState('default');
    const n = model.getNode(id);
    if (n) model.selectNode(n);
    this.api.renderNow();
  }
  private selectNote(id: string): void {
    const prev = this.sel, model = this.model;
    this.sel = { type: 'note', id };
    if (prev?.type === 'step') this.paint(prev.id);
    model.clearSelection();
    for (const l of model.getLinks()) if (l.state === 'selected') l.setState('default');
    this.setSel({ type: 'note', id });
  }

  // ---- the property panel ------------------------------------------------------------
  private renderPanel(): void { this.changed(); }
  /** Typing in a step's field: the canvas label follows on every keystroke. */
  editField(key: string, value: string): void {
    const sel = this.sel;
    if (!sel) return;
    if (!this.editBefore) this.editBefore = this.docFromModel();
    if (sel.type !== 'step') return;
    const node = this.model.getNode(sel.id);
    if (!node) return;
    const data = node.data, f = ACTIONS[data.action].fields.find((x) => x.key === key);
    data.props[key] = f?.type === 'number' ? Number(value) : value;
    if (f?.type === 'number') this.typed.set('k:' + key, value);
    this.afterEdit(node.id);
    // A select fires `change` together with `input`: its edit is one undo step
    // at once (React reports a select's change after the page's own listener).
    if (f?.type === 'select') this.commitEdit('Edit properties');
  }
  /** Typing in a Switch output: its name, or its rule's metric / operator / value. */
  editOut(i: number, which: 'label' | 'metric' | 'op' | 'value', value: string): void {
    const sel = this.sel;
    if (!sel) return;
    if (!this.editBefore) this.editBefore = this.docFromModel();
    if (sel.type !== 'step') return;
    const node = this.model.getNode(sel.id);
    const o = node?.data.outputs?.[i];
    if (!o) return;
    if (which === 'label') o.label = value;
    else if (o.rule) { (o.rule as any)[which] = which === 'value' ? Number(value) : value; if (which === 'value') this.typed.set('o:' + i, value); }
    this.afterEdit(node.id);
    if (which === 'metric' || which === 'op') this.commitEdit('Edit properties');   // selects: see editField
  }
  /** Typing in the selected note's title or text. */
  editNote(which: 'title' | 'text', value: string): void {
    const sel = this.sel;
    if (!sel) return;
    if (!this.editBefore) this.editBefore = this.docFromModel();
    if (sel.type !== 'note') return;
    const g = this.model.getGroup(sel.id);
    if (!g) return;
    g.setMetadata('note', { ...g.getMetadata('note'), [which]: value });
    if (which === 'title') g.name = value;
    this.refreshFrames();
    this.changed();
  }
  private commitEdit(name: string): void {
    if (this.editBefore) { this.commit(name, this.editBefore); this.editBefore = null; }
  }
  private afterEdit(id: string): void {
    this.paint(id);
    this.scheduleFrames();
    this.api.renderNow();
    this.changed();
  }
  /** A panel button: `act` is the JS page's data-act. */
  panelAct(act: string, arg?: string | number, rect?: DOMRect): void {
    const sel = this.sel;
    this.commitEdit('Edit properties');
    if (act === 'pick-trigger' && sel?.type === 'step') this.replacePlaceholder(sel.id, String(arg));
    else if (act === 'add-after' && rect) this.openMenu(rect.left - 310, rect.top, { mode: 'insert', port: String(arg) });
    else if (act === 'del-step' && sel?.type === 'step') this.deleteSteps([sel.id]);
    else if (act === 'del-link' && sel?.type === 'link') this.deleteLink(sel.id);
    else if (act === 'del-note' && sel?.type === 'note') this.deleteNote(sel.id);
    else if ((act === 'add-out' || act === 'rm-out') && sel?.type === 'step') {
      const node = this.model.getNode(sel.id), before = this.docFromModel(), outs = node.data.outputs;
      if (act === 'add-out') outs.splice(outs.length - 1, 0, { id: 'o' + Math.random().toString(36).slice(2, 6), label: `output ${outs.length}`, rule: { metric: 'latency_p95', op: '>', value: 1500 } });
      else if (outs.filter((o: any) => o.rule).length > 1) outs.splice(Number(arg), 1);
      this.typed.clear();
      this.paint(node.id);
      void this.commitWithLayout(act === 'add-out' ? 'Add output' : 'Remove output', before);
      this.renderPanel();
    }
  }

  // ---- edits ------------------------------------------------------------------------
  private stepNode(id: string, data: StepData, x: number, y: number): any { const n = this.buildNode({ id, x, y, data }); this.model.addNode(n); this.paint(id); return n; }
  private noteOfStep(id: string): any { return this.model.getGroups().find((g: any) => g.getMetadata('note') && g.members.has(id)); }
  /** "+" (splice: the new step takes over the port's lines) or a line dropped on canvas (a new branch). */
  private insertAfter(portId: string, action: string, { splice = true, world = null as { x: number; y: number } | null } = {}): string | null {
    this.settle(); this.test.stop(true);
    const model = this.model, src = model.getNodeByPortId(portId);
    if (!src) return null;
    const before = this.docFromModel();
    const id = newId(), data = newStepData(action);
    const at = world ?? { x: src.position.x + src.size.width + 90, y: src.position.y };
    this.stepNode(id, data, Math.round(at.x), Math.round(at.y));
    const old = splice ? model.getLinks().filter((l: any) => l.sourcePortId === portId) : [];
    for (const l of old) model.removeLink(l.id);
    this.addLink(newId(), portId, `${id}__in`);
    const firstOut = outputsOf(data)[0];
    for (const l of old) if (firstOut) this.addLink(newId(), portIdOf(id, data, firstOut), l.targetPortId);
    this.noteOfStep(src.id)?.addMember(id, model);
    this.lastInserted = id;
    this.selectStep(id);
    void this.commitWithLayout(`Add ${ACTIONS[action].app}`, before).then(() => this.reveal(id));
    return id;
  }
  private replacePlaceholder(phId: string, action: string): void {
    this.settle(); this.test.stop(true);
    const model = this.model, ph = model.getNode(phId);
    if (!ph) return;
    const before = this.docFromModel(), id = newId(), data = newStepData(action);
    this.stepNode(id, data, ph.position.x, ph.position.y);
    for (const l of model.getLinks().filter((x: any) => x.sourceNodeId === phId)) this.addLink(newId(), `${id}__out`, l.targetPortId);
    model.removeNode(phId);
    this.closeMenu();
    this.selectStep(id);
    void this.commitWithLayout(`Choose ${ACTIONS[action].app}`, before);
  }
  private deleteSteps(ids: string[]): void {
    this.settle(); this.test.stop(true);
    const model = this.model, before = this.docFromModel();
    for (const id of ids) {
      const node = model.getNode(id);
      if (!node) continue;
      const kind = kindOf(node.data);
      const ins = model.getLinks().filter((l: any) => l.targetNodeId === id);
      const outs = model.getLinks().filter((l: any) => l.sourceNodeId === id);
      // A one-in, one-out step heals the chain: its predecessor takes its lines.
      if (kind === 'app' && ins.length === 1) for (const l of outs) this.addLink(newId(), ins[0].sourcePortId, l.targetPortId);
      // The trigger leaves a "Choose a trigger" step that keeps its lines.
      if (kind === 'trigger') {
        const ph = newId();
        this.stepNode(ph, { action: PLACEHOLDER, props: {} }, node.position.x, node.position.y);
        for (const l of outs) this.addLink(newId(), `${ph}__out`, l.targetPortId);
      }
      for (const g of model.getGroups()) g.members.has(id) && g.removeMember(id, model);
      model.removeNode(id);
    }
    if (!model.getNodes().length) this.stepNode(newId(), { action: PLACEHOLDER, props: {} }, 0, 0);
    this.setSel(null);
    void this.commitWithLayout(ids.length > 1 ? `Delete ${ids.length} steps` : 'Delete step', before);
  }
  private deleteLink(id: string): void {
    this.settle(); this.test.stop(true);
    const before = this.docFromModel();
    this.model.removeLink(id);
    this.setSel(null);
    this.commit('Delete line', before);
    this.api.renderNow();
  }
  private deleteNote(id: string): void {
    this.settle();
    const before = this.docFromModel();
    this.model.removeGroup(id);
    this.setSel(null);
    this.commit('Delete note', before);
    this.refreshFrames();
  }

  // ---- the action menu ----------------------------------------------------------------
  private openMenu(clientX: number, clientY: number, mctx: MenuCtx): void {
    const host = this.host, menu = this.menu;
    this.menuCtx = mctx; menu.on = 0; menu.query = '';
    menu.build(mctx.mode === 'trigger');
    menu.open = true;
    menu.place(host.getBoundingClientRect(), clientX, clientY, (host.querySelector('#wf-menu') as HTMLElement | null)?.offsetWidth || 300);
    this.changed();
    // The framework shows the menu on its next render: focus the search then.
    let tries = 12;
    const focus = () => {
      const s = host.querySelector('#mn-search') as HTMLInputElement | null;
      if (!menu.open) return;
      if (s && s.offsetParent) s.focus({ preventScroll: true });
      else if (tries-- > 0) requestAnimationFrame(focus);
    };
    focus();
  }
  private openMenuAtStep(stepId: string, mctx: MenuCtx): void {
    const n = this.model.getNode(stepId), r = this.host.getBoundingClientRect();
    const c = this.api.viewport.worldToClient(n.position.x + n.size.width + 24, n.position.y, r);
    this.openMenu(c.x, c.y, mctx);
  }
  closeMenu(): void {
    if (!this.menu.open && !this.menuCtx) return;
    this.menu.open = false; this.menuCtx = null;
    this.changed();
  }
  /** A menu row was picked (clicked, or Enter on the highlighted one). */
  pick(action: string): void {
    const m = this.menuCtx;
    this.closeMenu();
    if (!m || !ACTIONS[action]) return;
    if (m.mode === 'trigger') this.replacePlaceholder(m.nodeId!, action);
    else this.insertAfter(m.port!, action, { splice: m.mode === 'insert', world: m.world ?? null });
  }
  /** Typing in the menu's search box. */
  menuSearch(q: string): void { this.menu.query = q; this.menu.on = 0; this.menu.build(this.menuCtx?.mode === 'trigger'); this.changed(); }
  /** A key in the menu's search box: ↑ / ↓ move the highlight, Enter picks, Escape closes. */
  menuKey(key: string): void {
    if (key === 'ArrowDown' || key === 'ArrowUp') {
      this.menu.move(key === 'ArrowDown' ? 1 : -1);
      this.changed();
      requestAnimationFrame(() => this.host.querySelector('.mn-item.on')?.scrollIntoView({ block: 'nearest' }));
    } else if (key === 'Enter' && this.menu.current) this.pick(this.menu.current);
    else if (key === 'Escape') this.closeMenu();
  }

  // ---- Test workflow (workflow-builder-run.ts walks the links) --------------------------
  /** Test workflow / Run again. */
  runWorkflow(): void {
    this.settle();
    this.closeMenu();
    void this.test.start();
  }
  // Pan (briefly animated) until a step sits inside the free part of the canvas.
  private reveal(id: string): void {
    const n = this.model?.getNode(id);
    if (!n) return;
    const r = this.host.getBoundingClientRect(), vp = this.api.viewport, z = vp.getZoom(), b = visualBox(this.boxOf(n));
    const a = vp.worldToClient(b.x0, b.y0, r), c = vp.worldToClient(b.x1, b.y1, r);
    const free = { left: r.left + 24, right: r.right - 24, top: r.top + 24, bottom: r.bottom - 24 };
    if (a.x >= free.left && c.x <= free.right && a.y >= free.top && c.y <= free.bottom) return;
    const dx = ((a.x + c.x) / 2 - (free.left + free.right) / 2) / z, dy = ((a.y + c.y) / 2 - (free.top + free.bottom) / 2) / z;
    const from = vp.getViewport(), t0 = performance.now(), dur = matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 300, job = ++this.panJob;
    const step = (now: number) => {
      if (job !== this.panJob) return;
      const k = dur ? Math.min(1, (now - t0) / dur) : 1, e = 1 - Math.pow(1 - k, 3);
      vp.setViewport({ ...from, x: from.x + dx * e, y: from.y + dy * e });
      if (k < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }

  // ---- top bar -------------------------------------------------------------------------
  private stepCount(): number { return this.model.getNodes().filter((n: any) => n.data?.action && n.data.action !== PLACEHOLDER).length; }
  async undo(): Promise<void> { this.settle(); await this.engine.undo(); this.syncHistory(); this.api.renderNow(); }
  async redo(): Promise<void> { this.settle(); await this.engine.redo(); this.syncHistory(); this.api.renderNow(); }
  save(): void {
    this.settle();
    const json = JSON.stringify({ title: this.title, savedAt: Date.now(), diagram: this.engine.serialize() });
    try { localStorage.setItem(KEY, json); } catch { this.toast('Your browser refused to store it (private mode?)'); return; }
    this.dirty = false;
    this.savedAt = Date.now();
    this.stateText = `Saved ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    this.toast(`Saved “${this.title}” · ${this.stepCount()} steps`);
  }
  load(): void {
    this.settle();
    let saved: any = null;
    try { saved = JSON.parse(localStorage.getItem(KEY) || 'null'); } catch { saved = null; }
    if (!saved?.diagram) { this.toast('Nothing saved yet: press Save first'); return; }
    const temp = new DiagramSerializer().deserialize(saved.diagram);
    const doc = this.docOf(temp, saved.title || 'Untitled workflow');
    const before = this.docFromModel();
    this.setSel(null);
    this.applyDoc(doc);
    this.commit('Load', before, doc);
    this.nav.frame();
    this.toast(`Loaded “${doc.title}” · ${doc.steps.filter((s) => s.data.action !== PLACEHOLDER).length} steps`);
  }
  newWorkflow(): void {
    this.settle();
    const before = this.docFromModel();
    this.setSel(null);
    const doc: WorkflowDoc = { v: 1, title: 'Untitled workflow', steps: [{ id: newId(), x: 0, y: 0, data: { action: PLACEHOLDER, props: {} } }], links: [], notes: [] };
    this.applyDoc(doc);
    this.commit('New workflow', before, doc);
    const vp = this.api.viewport;
    vp.setZoom(1);
    const c = vp.getViewport();
    vp.setViewport({ ...c, x: TILE / 2 - c.width / 2, y: TILE / 2 + 20 - c.height / 2 });
    this.toast('A blank workflow: click “Choose a trigger” to start');
  }
  /** Typing in the workflow's name (committed as "Rename" on change). */
  titleInput(v: string): void { if (!this.editBefore) this.editBefore = this.docFromModel(); this.title = v; this.changed(); }
  publish(): void {
    this.settle();
    const n = this.stepCount();
    this.toast(n ? `Published “${this.title}” · ${n} step${n === 1 ? '' : 's'} are live` : 'Nothing to publish yet: choose a trigger first');
  }

  // ---- a fresh sample -------------------------------------------------------------------
  private reset(): void {
    this.settle(); this.test.stop(true);
    this.test.open = false;
    this.closeMenu();
    this.model.clearSelection();
    this.sel = null; this.editBefore = null;
    const doc = sampleWorkflow();
    this.applyDoc(doc);
    const pos = this.computeLayout();
    for (const [id, p] of pos) this.model.getNode(id).setPosition(p.x, p.y);
    this.refreshFrames();
    this.cm.clear();
    this.syncHistory();
    this.nav.frame();
    this.renderPanel();
    this.dirty = false;
    if (!this.savedAt) this.stateText = 'Not saved yet';
    this.nav.zoomed(this.api.viewport.getZoom());
    this.changed();
  }
}

// Workflow automation builder — the automatic left-to-right arrangement.
// (A TypeScript copy of demos/interaction/workflow-builder-layout.js; the same
// file sits next to the demo in the React, Vue, Angular and Qwik apps.)
//
// A tidy layered tree, framework-free and deterministic:
//   • COLUMNS by longest path from the trigger, so every line runs left → right;
//     each column is as wide as its widest step (labels and output names
//     included), and the tiles of a column share one centre line.
//   • ROWS by subtree bands: every leaf gets its own band, a parent sits centred
//     on its first and last child, and two subtrees never share a band, so no
//     two steps can overlap whatever the user builds.
//   • NOTES (sticky notes that hold a sub-flow): when a run of siblings enters
//     a note, the band above them is reserved for the note's header, and the
//     note's frame is the box around its members plus that header — so the
//     frame never covers a step that is not in it.
//
// Input positions only anchor the result (the first trigger stays put); the
// shape of the graph decides everything else.

export interface LayoutOptions { hGap: number; vGap: number; rootGap: number; padX: number; padBottom: number; minNoteWidth: number }
/** A step's tile box and how far its drawing spills past it. */
export interface LayoutNode { id: string; x: number; y: number; w: number; h: number; left: number; right: number; top: number; bottom: number; first?: boolean }
export interface LayoutLink { from: string; to: string; order: number }
export interface LayoutNote { id: string; members: string[]; header: number }
export interface Box { x0: number; y0: number; x1: number; y1: number }
export interface Frame { x: number; y: number; width: number; height: number }

export const LAYOUT: LayoutOptions = { hGap: 30, vGap: 22, rootGap: 44, padX: 22, padBottom: 16, minNoteWidth: 360 };

/**
 * A step's drawn extent. `n` has the tile box (x, y, w, h) and how far the
 * drawing spills past it: `left`/`right` beyond the tile's sides, `top` above
 * it (a status badge), `bottom` measured from the tile's top edge.
 */
export const visualBox = (n: Omit<LayoutNode, 'id'> & { id?: string }, x = n.x, y = n.y): Box => ({ x0: x - n.left, y0: y - n.top, x1: x + n.w + n.right, y1: y + n.bottom });

/** A note's frame around its members' drawn boxes, `header` px reserved on top. */
export function noteFrame(boxes: Box[], header: number, o: LayoutOptions = LAYOUT): Frame | null {
  if (!boxes.length) return null;
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const b of boxes) { x0 = Math.min(x0, b.x0); y0 = Math.min(y0, b.y0); x1 = Math.max(x1, b.x1); y1 = Math.max(y1, b.y1); }
  return { x: x0 - o.padX, y: y0 - header, width: Math.max(x1 - x0 + 2 * o.padX, o.minNoteWidth), height: y1 - y0 + header + o.padBottom };
}

/**
 * @param {{ nodes: Array<{id,x,y,w,h,left,right,top,bottom,first?:boolean}>,
 *           links: Array<{from,to,order}>,
 *           notes: Array<{id, members: string[], header: number}> }} g
 * @returns {{ pos: Map<string,{x,y}>, frames: Map<string,{x,y,width,height}>, rank: Map<string,number> }}
 */
export function layoutFlow(g: { nodes: LayoutNode[]; links: LayoutLink[]; notes: LayoutNote[] }, o: LayoutOptions = LAYOUT):
  { pos: Map<string, { x: number; y: number }>; frames: Map<string, Frame>; rank: Map<string, number> } {
  const byId = new Map(g.nodes.map((n) => [n.id, n]));
  const out = new Map<string, LayoutLink[]>(g.nodes.map((n) => [n.id, []]));
  const indeg = new Map<string, number>(g.nodes.map((n) => [n.id, 0]));
  for (const l of g.links) {
    if (l.from === l.to || !byId.has(l.from) || !byId.has(l.to)) continue;
    out.get(l.from)!.push(l);
    indeg.set(l.to, indeg.get(l.to)! + 1);
  }
  for (const list of out.values()) list.sort((a, b) => a.order - b.order);

  // ---- roots, then a DFS spanning tree (back edges noted, never followed) ----
  const byPlace = (a: LayoutNode, b: LayoutNode): number => (b.first ? 1 : 0) - (a.first ? 1 : 0) || a.y - b.y || a.x - b.x || (a.id < b.id ? -1 : 1);
  const roots = g.nodes.filter((n) => indeg.get(n.id) === 0).sort(byPlace).map((n) => n.id);
  const kids = new Map<string, string[]>(g.nodes.map((n) => [n.id, []]));
  const seen = new Set<string>(), onStack = new Set<string>(), back = new Set<LayoutLink>(), top: string[] = [];
  const dfs = (id: string): void => {
    seen.add(id); onStack.add(id);
    for (const l of out.get(id)!) {
      if (!seen.has(l.to)) { kids.get(id)!.push(l.to); dfs(l.to); }
      else if (onStack.has(l.to)) back.add(l);
    }
    onStack.delete(id);
  };
  for (const r of roots) if (!seen.has(r)) { top.push(r); dfs(r); }
  // A cycle with no way in: start it at its top-left step.
  for (const n of [...g.nodes].sort(byPlace)) if (!seen.has(n.id)) { top.push(n.id); dfs(n.id); }

  // ---- columns: longest path over the forward edges ------------------------
  const rank = new Map<string, number>(g.nodes.map((n) => [n.id, 0]));
  const fwd = g.links.filter((l) => !back.has(l) && l.from !== l.to && byId.has(l.from) && byId.has(l.to));
  const deg = new Map<string, number>(g.nodes.map((n) => [n.id, 0]));
  for (const l of fwd) deg.set(l.to, deg.get(l.to)! + 1);
  const queue = g.nodes.filter((n) => deg.get(n.id) === 0).map((n) => n.id);
  while (queue.length) {
    const id = queue.shift()!;
    for (const l of fwd) {
      if (l.from !== id) continue;
      rank.set(l.to, Math.max(rank.get(l.to)!, rank.get(id)! + 1));
      deg.set(l.to, deg.get(l.to)! - 1);
      if (deg.get(l.to) === 0) queue.push(l.to);
    }
  }
  const maxRank = Math.max(0, ...rank.values());
  const L = new Array(maxRank + 1).fill(0), R = new Array(maxRank + 1).fill(0);
  for (const n of g.nodes) {
    const r = rank.get(n.id)!;
    L[r] = Math.max(L[r], n.w / 2 + n.left);
    R[r] = Math.max(R[r], n.w / 2 + n.right);
  }
  const cx = [0];
  for (let r = 1; r <= maxRank; r++) cx[r] = cx[r - 1] + R[r - 1] + o.hGap + L[r];

  // ---- rows: bands, with note headers reserved above a run of members ------
  const noteOf = new Map<string, string>();
  const noteById = new Map(g.notes.map((nt) => [nt.id, nt]));
  for (const nt of g.notes) for (const m of nt.members) if (!noteOf.has(m)) noteOf.set(m, nt.id);
  // Consecutive siblings that ENTER the same note (the parent is not in it).
  type Run = { note: string | null; ids: string[] };
  const runsOf = (parent: string | null, list: string[]): Run[] => {
    const runs: Run[] = [];
    for (const id of list) {
      const nt = noteOf.get(id);
      const enters = nt && (parent === null ? undefined : noteOf.get(parent)) !== nt ? nt : null;
      const last = runs[runs.length - 1];
      if (enters && last && last.note === enters) last.ids.push(id);
      else runs.push({ note: enters, ids: [id] });
    }
    return runs;
  };
  const band = new Map<string, number>(), kidsBand = new Map<string, number>();
  const runSize = (r: Run, gap: number): number => r.ids.reduce((s, id) => s + band.get(id)!, 0) + (r.note ? noteById.get(r.note)!.header + o.padBottom : 0) + gap;
  const measure = (id: string): void => {
    const n = byId.get(id)!;
    for (const k of kids.get(id)!) measure(k);
    const total = runsOf(id, kids.get(id)!).reduce((s, r) => s + runSize(r, 0), 0);
    kidsBand.set(id, total);
    band.set(id, Math.max(n.top + n.bottom + o.vGap, total));
  };
  const center = new Map<string, number>();
  const place = (id: string, y0: number): void => {
    const n = byId.get(id)!, list = kids.get(id)!;
    let y = y0 + (band.get(id)! - kidsBand.get(id)!) / 2;
    for (const r of runsOf(id, list)) {
      if (r.note) y += noteById.get(r.note)!.header;
      for (const k of r.ids) { place(k, y); y += band.get(k)!; }
      if (r.note) y += o.padBottom;
    }
    const lo = y0 + n.top + n.h / 2, hi = y0 + band.get(id)! - o.vGap - n.bottom + n.h / 2;
    const want = list.length ? (center.get(list[0])! + center.get(list[list.length - 1])!) / 2 : lo;
    center.set(id, Math.max(lo, Math.min(hi, want)));
  };
  for (const r of top) measure(r);
  let y = 0;
  for (const r of runsOf(null, top)) {
    if (r.note) y += noteById.get(r.note)!.header;
    for (const id of r.ids) { place(id, y); y += band.get(id)! + o.rootGap; }
    if (r.note) y += o.padBottom;
  }

  // ---- positions, anchored on the first root's current tile ----------------
  const pos = new Map<string, { x: number; y: number }>();
  for (const n of g.nodes) pos.set(n.id, { x: cx[rank.get(n.id)!] - n.w / 2, y: center.get(n.id)! - n.h / 2 });
  const anchor = top.length ? byId.get(top[0]) : null;
  if (anchor && Number.isFinite(anchor.x) && Number.isFinite(anchor.y)) {
    const p = pos.get(anchor.id)!, dx = anchor.x - p.x, dy = anchor.y - p.y;
    for (const v of pos.values()) { v.x = Math.round(v.x + dx); v.y = Math.round(v.y + dy); }
  }

  const frames = new Map<string, Frame>();
  for (const nt of g.notes) {
    const boxes = nt.members.filter((m) => byId.has(m)).map((m) => visualBox(byId.get(m)!, pos.get(m)!.x, pos.get(m)!.y));
    const f = noteFrame(boxes, nt.header, o);
    if (f) frames.set(nt.id, f);
  }
  return { pos, frames, rank };
}

// Workflow automation builder — how a step is drawn. (A TypeScript copy of
// demos/interaction/workflow-builder-steps.js; the same file sits next to the
// demo in the React, Vue, Angular and Qwik apps.)
//
// Framework-free: a step's data ({ action, props, outputs }) → its tile box,
// its painted content (the structured, sanitised HTML the canvas renders in
// the node's foreignObject: tile, icon, two-line label, a "+" per output and
// the output names), its port list, the line styles, and the panel's form
// fragments (as data here: each framework's template renders them). The page
// owns the engine; this module only describes.

import { ACTIONS, PLACEHOLDER, outputsOf, type Field, type Output, type StepData } from './workflow-builder-catalog';

/** The structured, sanitised HTML the canvas paints in a node's foreignObject. */
export interface HtmlContent {
  tag: string; className?: string; text?: string; children?: HtmlContent[];
  attrs?: Record<string, string>; style?: Record<string, string>;
}
/** A step's tile box + how far its drawing spills (see layout.visualBox). */
export interface Geom { w: number; h: number; left: number; right: number; top: number; bottom: number; outs: number[] }
export interface PortSpec { id: string; type: 'input' | 'output'; side: 'left' | 'right'; x: number; y: number }

export const esc = (s: unknown): string => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c as '&']);

// ---- step geometry ---------------------------------------------------------
export const TILE = 56, CAP_W = 48, LABEL_W = 170;
export const FONT = 'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';
export const kindOf = (data: StepData): string => (data.action === PLACEHOLDER ? 'placeholder' : ACTIONS[data.action]?.kind ?? 'app');
export const isLogic = (data: StepData): boolean => ['condition', 'switch'].includes(kindOf(data));
export const portIdOf = (stepId: string, data: StepData, out: Output): string => (kindOf(data) === 'switch' ? `${stepId}__o_${out.id}` : `${stepId}__${out.id}`);
export const appNameOf = (data: StepData): string => (data.action === PLACEHOLDER ? 'Start here' : ACTIONS[data.action]?.app ?? data.action);
export const summaryOf = (data: StepData): string => {
  if (data.action === PLACEHOLDER) return 'Choose a trigger';
  const a = ACTIONS[data.action];
  try { return a ? a.summary(data.props) : ''; } catch { return a?.label ?? ''; }
};
export const iconOf = (data: StepData): string => ACTIONS[data.action]?.icon ?? 'delay';
let measureCtx: CanvasRenderingContext2D | null = null;
export const textWidth = (text: unknown, font: string): number => {
  measureCtx ??= document.createElement('canvas').getContext('2d')!;
  measureCtx.font = font;
  return measureCtx.measureText(String(text)).width;
};
/** Tile box + how far its drawing spills (see layout.visualBox). */
export function geomOf(data: StepData): Geom {
  const lines = textWidth(summaryOf(data), `550 11.5px ${FONT}`) > LABEL_W - 6 ? 2 : 1;
  const labelH = 7 + 14 + 15 * lines + 4;
  if (!isLogic(data)) {
    const side = LABEL_W / 2 - TILE / 2;
    return { w: TILE, h: TILE, left: side, right: Math.max(side, 32), top: 8, bottom: TILE + labelH, outs: [TILE / 2] };
  }
  const outs = outputsOf(data);
  const h = Math.max(64, outs.length * 26 + 12);
  const widest = Math.max(0, ...outs.map((o) => textWidth(o.label, `10px ${FONT}`)));
  const side = LABEL_W / 2 - CAP_W / 2;
  return { w: CAP_W, h, left: side, right: Math.max(side, 26 + widest + 8), top: 8, bottom: h + labelH,
    outs: outs.map((_, i) => Math.round((h * (i + 1)) / (outs.length + 1))) };
}

// ---- a step → its painted content (structured, sanitised HTML) ---------------
export function stepContent(id: string, data: StepData, flags: { sel?: boolean; status?: string } = {}): HtmlContent {
  const kind = kindOf(data), g = geomOf(data);
  const cls = ['wf-node', kind === 'placeholder' ? 'wf-ph' : isLogic(data) ? 'wf-logic' : kind === 'trigger' ? 'wf-trigger wf-app' : 'wf-app'];
  if (flags.sel) cls.push('wf-sel');
  if (flags.status) cls.push('st-' + flags.status);
  const kids: HtmlContent[] = [];
  kids.push(kind === 'placeholder'
    ? { tag: 'div', className: 'wf-tile', text: '+' }
    : { tag: 'div', className: 'wf-tile', children: [{ tag: 'span', className: `wf-ic ic-${iconOf(data)}` }] });
  if (kind === 'trigger') kids.push({ tag: 'span', className: 'wf-bolt', text: '⚡' });
  if (flags.status) kids.push({ tag: 'span', className: 'wf-badge', text: ({ success: '✓', failed: '!', stopped: '■' } as Record<string, string>)[flags.status] ?? '' });
  kids.push({ tag: 'div', className: 'wf-label', children: [
    { tag: 'div', className: 'wf-app-name', text: appNameOf(data) },
    { tag: 'div', className: 'wf-sum', text: summaryOf(data) || '—' },
  ] });
  if (kind !== 'placeholder') {
    outputsOf(data).forEach((o, i) => {
      const y = g.outs[i] ?? g.h / 2;
      kids.push({ tag: 'span', className: `wf-plus wfp-${portIdOf(id, data, o)}`, text: '+',
        attrs: { title: o.label ? `Add a step after “${o.label}”` : 'Add the next step' }, style: { left: `${g.w + 16}px`, top: `${y}px` } });
      if (o.label) kids.push({ tag: 'span', className: 'wf-out-label', text: o.label, style: { left: `${g.w + 27}px`, top: `${y - 4}px` } });
    });
  }
  return { tag: 'div', className: cls.join(' '), children: kids };
}

// ---- ports -------------------------------------------------------------------
export function portList(id: string, data: StepData): PortSpec[] {
  const g = geomOf(data), kind = kindOf(data), list: PortSpec[] = [];
  if (kind !== 'trigger' && kind !== 'placeholder') list.push({ id: `${id}__in`, type: 'input', side: 'left', x: 0, y: g.h / 2 });
  outputsOf(data).forEach((o, i) => list.push({ id: portIdOf(id, data, o), type: 'output', side: 'right', x: g.w, y: g.outs[i] ?? g.h / 2 }));
  return list;
}
export const portConfig = (p: PortSpec) => ({
  id: p.id, type: p.type, side: p.side, shape: { shape: 'circle', size: 10 },
  layout: { strategy: 'absolute', args: { units: 'px', x: p.x, y: p.y } },
  style: { fill: '#ffffff', stroke: '#3B52D9', strokeWidth: 1.5 },
});
// ---- lines -------------------------------------------------------------------
export const DARK = matchMedia('(prefers-color-scheme: dark)');
export const lineStyle = (mode?: 'active' | 'done'): Record<string, unknown> => {
  const base = DARK.matches ? '#5b6377' : '#a8b0c0';
  if (mode === 'active') return { stroke: DARK.matches ? '#8b9cf2' : '#3B52D9', strokeWidth: 2.4, arrowHead: { type: 'none' }, animation: { type: 'flow', speed: 'fast', direction: 'forward' } };
  if (mode === 'done') return { stroke: '#16a34a', strokeWidth: 2.2, arrowHead: { type: 'none' }, animation: { type: 'none' } };
  return { stroke: base, strokeWidth: 1.6, arrowHead: { type: 'none' }, animation: { type: 'none' } };
};
// ---- the property panel's fragments ------------------------------------------
// The JS page builds these as HTML strings; here they are data, and each
// framework's template renders the markup (the same classes and data-* names).

/** The panel's step tile: its classes, and its icon (null: the placeholder's "+"). */
export const tileOf = (data: StepData): { cls: string; icon: string | null } => {
  const k = kindOf(data);
  return { cls: ['pn-tile', k === 'trigger' ? 'sq' : '', isLogic(data) ? 'logic' : ''].filter(Boolean).join(' '),
    icon: k === 'placeholder' ? null : iconOf(data) };
};
/** A select field's options as { value, label }. */
export const optionsOf = (f: Field): Array<{ value: string; label: string }> =>
  (f.options ?? []).map((o) => ({ value: o, label: f.optionLabels?.[o] ?? o }));

// Workflow automation builder — the right-hand property panel, as data.
//
// Framework-free: what the panel shows for the current selection (a step's
// form, a Switch's outputs and rules, a line's two ends, a note's editor, the
// placeholder's trigger picks, the empty invitation). The JS page writes this
// as HTML strings into #panel; here it is one plain object every framework's
// template renders with the same classes and data-* names. The same file sits
// next to the workflow-builder demo in the React, Vue, Angular and Qwik apps.
import { ACTIONS, PLACEHOLDER, outputsOf, type Rule, type StepData } from './workflow-builder-catalog';
import { kindOf, portIdOf, appNameOf, summaryOf, tileOf, optionsOf } from './workflow-builder-steps';

export interface PanelTile { cls: string; icon: string | null }
export interface PanelField {
  key: string; label: string; type: string; required: boolean; placeholder: string;
  options: Array<{ value: string; label: string }>; value: string;
}
export interface PanelOut { i: number; label: string; rule: Rule | null; value: string }
export interface PanelEnd { tile: PanelTile; app: string; sub: string }
/** The panel: one shape for every mode (the fields a mode does not use stay empty). */
export interface PanelView {
  mode: 'placeholder' | 'step' | 'link' | 'note' | 'multi' | 'empty';
  tile: PanelTile | null;
  kind: string;                 // the small caps line over the title
  title: string;
  triggers: Array<{ key: string; label: string; app: string; icon: string }>;
  fields: PanelField[];
  isSwitch: boolean;
  outputs: PanelOut[];
  next: Array<{ port: string; label: string }>;
  from: PanelEnd | null;
  to: PanelEnd | null;
  noteTitle: string;
  noteText: string;
  count: number;                // multi: the steps selected
  steps: number;                // empty: the counts
  lines: number;
}
/** What is selected: a step, a line, a note, several steps, or nothing. */
export type Sel = { type: 'step' | 'link' | 'note'; id: string } | { type: 'multi'; ids: string[] } | null;

export const EMPTY_PANEL: PanelView = {
  mode: 'empty', tile: null, kind: '', title: '', triggers: [], fields: [], isSwitch: false, outputs: [], next: [],
  from: null, to: null, noteTitle: '', noteText: '', count: 0, steps: 0, lines: 0,
};

export function selectionExists(model: any, sel: NonNullable<Sel>): boolean {
  if (sel.type === 'step') return !!model?.getNode(sel.id);
  if (sel.type === 'link') return !!model?.getLink(sel.id);
  if (sel.type === 'note') return !!model?.getGroup(sel.id);
  return true;
}

/**
 * The panel for `sel` on `model`. `typed` holds what a number box shows while
 * it is typed in ('k:<field>' / 'o:<output>'): the step keeps the number, so an
 * emptied box would otherwise snap back to 0.
 */
export function panelView(model: any, sel: Sel, typed: Map<string, string>): PanelView {
  if (!model) return EMPTY_PANEL;
  if (sel?.type === 'step' && model.getNode(sel.id)) {
    const node = model.getNode(sel.id), data: StepData = node.data, a = ACTIONS[data.action], kind = kindOf(data);
    if (kind === 'placeholder') {
      return { ...EMPTY_PANEL, mode: 'placeholder', tile: tileOf(data), kind: 'Start here', title: 'Choose a trigger',
        triggers: Object.entries(ACTIONS).filter(([, x]) => x.kind === 'trigger').map(([k, x]) => ({ key: k, label: x.label, app: x.app, icon: x.icon })) };
    }
    const outs = outputsOf(data);
    return { ...EMPTY_PANEL, mode: 'step', tile: tileOf(data),
      kind: `${a.cat === 'Triggers' ? 'Trigger' : a.cat === 'Logic' ? 'Logic' : 'Action'} · ${a.app}`, title: a.label,
      fields: a.fields.map((f) => ({ key: f.key, label: f.label, type: f.type, required: !!f.required, placeholder: f.placeholder ?? '',
        options: optionsOf(f), value: typed.get('k:' + f.key) ?? String(data.props[f.key] ?? '') })),
      isSwitch: kind === 'switch',
      outputs: kind === 'switch' ? (data.outputs ?? []).map((o, i) => ({ i, label: o.label, rule: o.rule ?? null,
        value: typed.get('o:' + i) ?? (o.rule ? String(o.rule.value) : '') })) : [],
      next: outs.map((o) => ({ port: portIdOf(node.id, data, o), label: `+ After ${o.label || a.app}` })) };
  }
  if (sel?.type === 'link' && model.getLink(sel.id)) {
    const l = model.getLink(sel.id), s = model.getNode(l.sourceNodeId), t = model.getNode(l.targetNodeId);
    const outLabel = s?.data ? outputsOf(s.data).find((o) => portIdOf(s.id, s.data, o) === l.sourcePortId)?.label : '';
    const end = (n: any, sub: string): PanelEnd | null => (n?.data ? { tile: tileOf(n.data), app: appNameOf(n.data), sub: `${summaryOf(n.data)}${sub ? ` · ${sub}` : ''}` } : null);
    const app = (n: any) => (n?.data ? appNameOf(n.data) : '');
    return { ...EMPTY_PANEL, mode: 'link', kind: 'Line', title: `${app(s)} → ${app(t)}`,
      from: end(s, outLabel ? `output “${outLabel}”` : 'output'), to: end(t, 'input') };
  }
  if (sel?.type === 'note' && model.getGroup(sel.id)) {
    const g = model.getGroup(sel.id), nt = g.getMetadata('note'), n = g.members.size;
    return { ...EMPTY_PANEL, mode: 'note', kind: 'Sticky note', title: `${n} step${n === 1 ? '' : 's'} inside`, noteTitle: nt.title, noteText: nt.text };
  }
  if (sel?.type === 'multi') return { ...EMPTY_PANEL, mode: 'multi', count: sel.ids.length };
  const steps = model.getNodes().filter((n: any) => n.data?.action && n.data.action !== PLACEHOLDER).length;
  return { ...EMPTY_PANEL, mode: 'empty', steps, lines: model.getLinks().length };
}

// Workflow automation builder — the add-step menu's state: its search, its
// sections, the highlighted row, and where it sits over the canvas.
//
// Framework-free: the controller opens it (from a "+", a panel button, a line
// let go on empty canvas, or the placeholder) and decides what a pick does;
// each framework's template renders `groups` and binds `query`. The same file
// sits next to the workflow-builder demo in the React, Vue, Angular and Qwik apps.
import { ACTIONS, CATEGORIES } from './workflow-builder-catalog';

export interface MenuItem { key: string; app: string; label: string; icon: string; index: number }
export interface MenuGroup { cat: string; items: MenuItem[] }

export class StepMenu {
  open = false;
  query = '';
  groups: MenuGroup[] = [];
  /** The highlighted row (Enter picks it). */
  on = 0;
  style = { left: '0px', top: '0px', bottom: '' };
  private items: string[] = [];

  /** The highlighted action, if any row matches. */
  get current(): string | undefined { return this.items[this.on]; }

  /** Rebuild the rows for the current query: the triggers only, or every other section. */
  build(triggersOnly: boolean): void {
    const q = this.query.trim().toLowerCase();
    const cats = triggersOnly ? ['Triggers'] : CATEGORIES.filter((c) => c !== 'Triggers');
    const items: string[] = [], groups: MenuGroup[] = [];
    for (const c of cats) {
      const list = Object.entries(ACTIONS).filter(([, a]) => a.cat === c && (!q || `${a.app} ${a.label} ${c}`.toLowerCase().includes(q)));
      if (!list.length) continue;
      groups.push({ cat: c, items: list.map(([k, a]) => ({ key: k, app: a.app, label: a.label, icon: a.icon, index: items.push(k) - 1 })) });
    }
    this.groups = groups;
    this.items = items;
    this.on = Math.min(this.on, Math.max(0, items.length - 1));
  }

  /**
   * Sit at a client point inside the canvas rect `r`: below the point when the
   * full list fits, else growing UP from it (its height changes as you search,
   * so the anchored edge must stay put). `mw` is the menu's width.
   */
  place(r: DOMRect, clientX: number, clientY: number, mw: number): void {
    const room = r.height - (clientY - r.top);
    const left = Math.round(Math.min(Math.max(8, clientX - r.left), r.width - mw - 8)) + 'px';
    if (room >= 420 || clientY - r.top < 420) this.style = { left, top: Math.round(Math.min(Math.max(8, clientY - r.top), r.height - 418)) + 'px', bottom: '' };
    else this.style = { left, top: '', bottom: Math.round(Math.max(8, r.bottom - clientY - 24)) + 'px' };
  }

  /** ↑ / ↓: move the highlight, wrapping round. */
  move(delta: 1 | -1): void {
    this.on = (this.on + delta + this.items.length) % Math.max(1, this.items.length);
  }
}

// Workflow automation builder — Test workflow: walk the links from the
// trigger, evaluate the rules, and keep the run card's state.
//
// The run starts at the trigger; each step spins (620 ms × speed) then turns
// green, the active line animates, the Condition follows the branch its rule
// picks for the sample commit, the Switch follows the output the simulated
// health result picks, and a step whose required field is empty FAILS. Stop
// halts it. Framework-free: the controller hands it the canvas (RunHost); each
// framework's template renders `log`, the chip and the inputs. The same file
// sits next to the workflow-builder demo in the React, Vue, Angular and Qwik apps.
import { ACTIONS, HEALTH, PLACEHOLDER, outputsOf, missingField, type StepData } from './workflow-builder-catalog';
import { kindOf, isLogic, portIdOf, summaryOf, iconOf, lineStyle } from './workflow-builder-steps';

/** A run-log row: cls running / success / failed / stopped, or 'note' (a line of text in `msg`). */
export interface LogRow { id: number; cls: string; icon: string; name: string; msg: string; st: string }

/** What a run needs from the page. */
export interface RunHost {
  readonly model: any;           // the live DiagramModel
  paint(id: string): void;       // repaint a step (its status badge)
  reveal(id: string): void;      // pan until the step is in view
  renderNow(): void;
  miniRefresh(): void;
  scrollLog(): void;             // the log's newest row into view
  changed(): void;               // re-render the component
}

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

export class TestRun {
  // ---- what the run card renders ----------------------------------------------
  open = false;
  /** Stop shows while a run is going, Run again otherwise. */
  active = false;
  msg = 'release: v2.14.0 faster checkout totals';
  health = 'degraded';
  chipText = 'Ready';
  chipCls = 'idle';
  log: LogRow[] = [];
  readonly healthOptions = Object.entries(HEALTH).map(([k, h]) => ({ value: k, label: h.label }));
  /** The delays are multiplied by this. */
  speed = 1;
  /** Each step's state in the current run (the badges and the minimap read it). */
  readonly status = new Map<string, string>();
  running = false;

  private host: RunHost;
  private token = 0;
  private seq = 0;
  constructor(host: RunHost) { this.host = host; }

  /** A fresh canvas: nothing has run (no repaint — its steps are new). */
  clear(): void {
    this.token++;
    this.running = false;
    this.status.clear();
    this.log = []; this.open = false; this.active = false; this.chipText = 'Ready'; this.chipCls = 'idle';
  }
  setStatus(id: string, st: string | null): void { if (st) this.status.set(id, st); else this.status.delete(id); this.host.paint(id); }
  private setChip(text: string, cls: string): void { this.chipText = text; this.chipCls = cls; this.host.changed(); }
  /** Badges off, lines back to grey, the log emptied. */
  reset(): void {
    const had = [...this.status.keys()];
    this.status.clear();
    for (const id of had) this.host.paint(id);
    for (const l of this.host.model.getLinks()) l.updateStyle(lineStyle());
    this.log = [];
    this.host.renderNow();
    this.host.miniRefresh();
    this.host.changed();
  }
  /** Halt a run; `silent` also wipes what it showed (every edit does this). */
  stop(silent: boolean): void {
    if (!this.running) { if (silent && this.status.size) this.reset(); return; }
    this.token++;
    this.running = false;
    for (const [id, st] of this.status) if (st === 'running') this.setStatus(id, 'stopped');
    for (const l of this.host.model.getLinks()) if (l.style?.animation?.type === 'flow') l.updateStyle(lineStyle());
    for (const row of this.log) if (row.cls === 'running') { row.cls = 'stopped'; row.msg = 'Stopped before it finished'; row.st = '■'; }
    this.setChip('Stopped', 'idle');
    this.active = false;
    if (silent) this.reset();
    this.host.changed();
  }
  /** The card's Stop. */
  halt(): void { this.stop(false); }
  /** The card's ×. */
  close(): void { this.stop(true); this.open = false; this.host.changed(); }
  setMsg(v: string): void { this.msg = v; this.host.changed(); }
  setHealth(v: string): void { this.health = v; this.host.changed(); }

  private logRow(data: StepData, name: string): (st: string, msg: string) => void {
    const row: LogRow = { id: ++this.seq, cls: 'running', icon: iconOf(data), name, msg: 'Running…', st: '' };
    this.log = [...this.log, row];
    this.host.changed();
    this.host.scrollLog();
    return (st, msg) => {
      row.cls = st; row.st = st === 'success' ? '✓' : st === 'failed' ? '!' : ''; row.msg = msg;
      this.log = [...this.log];
      this.host.changed();
    };
  }
  private note(text: string): void {
    this.log = [...this.log, { id: ++this.seq, cls: 'note', icon: '', name: '', msg: text, st: '' }];
    this.host.changed();
  }

  /** Run from the trigger (Test workflow / Run again). */
  async start(): Promise<void> {
    this.stop(true);
    this.reset();
    this.open = true;
    const model = this.host.model;
    const token = ++this.token;
    this.running = true;
    this.setChip('Running', '');
    this.active = true;
    const trig = model.getNodes().find((n: any) => kindOf(n.data ?? {}) === 'trigger' && !model.getLinks().some((l: any) => l.targetNodeId === n.id));
    let failed = false;
    if (!trig) {
      this.note('This workflow has no trigger yet: choose one first.');
      failed = true;
    } else {
      const sim = { commit: { message: this.msg, branch: trig.data.props.branch || 'main', author: 'maya.k' }, health: this.health };
      this.note(`Sample commit by maya.k on ${sim.commit.branch} · health check will report “${HEALTH[sim.health].label}”`);
      const visited = new Set<string>();
      const visit = async (id: string, via: any): Promise<void> => {
        if (token !== this.token || visited.has(id)) return;
        visited.add(id);
        const node = model.getNode(id);
        if (!node?.data?.action || node.data.action === PLACEHOLDER) return;
        const data: StepData = node.data, a = ACTIONS[data.action];
        if (via) via.updateStyle(lineStyle('active'));
        this.setStatus(id, 'running');
        const row = this.logRow(data, `${a.app} · ${summaryOf(data)}`);
        this.host.reveal(id);
        this.host.renderNow();
        await sleep(620 * this.speed);
        if (token !== this.token) return;
        if (via && model.getLink(via.id)) via.updateStyle(lineStyle('done'));
        const miss = missingField(data);
        if (miss) { this.setStatus(id, 'failed'); row('failed', `${miss.label} is empty — fill it in the panel`); failed = true; return; }
        let res: { msg?: string; out?: string };
        try { res = a.run(data.props, sim, outputsOf(data)) || {}; } catch (err: any) { res = { msg: String(err?.message || err) }; }
        this.setStatus(id, 'success');
        row('success', res.msg || 'Done');
        const outs = outputsOf(data).filter((o) => !isLogic(data) || o.id === res.out);
        for (const o of outs) {
          const pid = portIdOf(id, data, o);
          for (const l of model.getLinks().filter((x: any) => x.sourcePortId === pid)) await visit(l.targetNodeId, l);
        }
      };
      await visit(trig.id, null);
    }
    if (token !== this.token) return;
    this.running = false;
    this.setChip(failed ? 'Failed' : 'Succeeded', failed ? 'bad' : 'ok');
    this.active = false;
    this.host.miniRefresh();
    this.host.changed();
  }
}

// Workflow automation builder — the navigator card: a minimap (the sticky
// notes drawn under its steps, a step coloured by its run state), the zoom
// slider and its readout, Fit and Fit width.
//
// Framework-free: the controller mounts it on the canvas instance; each
// framework's template renders the card's buttons from `zoomPct`, `mmOn` and
// `flashing`. The same file sits next to the workflow-builder demo in the
// React, Vue, Angular and Qwik apps.
import { createMiniMap } from '@grafloria/element';
import { visualBox } from './workflow-builder-layout';
import { geomOf, DARK } from './workflow-builder-steps';

const SVG = 'http://www.w3.org/2000/svg';
const RUN_COLOUR: Record<string, string> = { running: '#f59e0b', success: '#16a34a', failed: '#dc2626' };

export class Navigator {
  // ---- what the card renders --------------------------------------------------------
  zoomPct = 100;
  mmOn = true;
  /** The button that just fired (a short highlight). */
  flashing: 'fit' | 'fitw' | null = null;

  private api: any = null;
  private model: any = null;
  private host!: HTMLElement;
  private mm: any = null;
  private mmNotes: SVGGElement | null = null;
  private raf = 0;
  private changed: () => void;
  constructor(changed: () => void) { this.changed = changed; }

  /** Mount the minimap in `el`; `status` is the run's step states. */
  mount(api: any, host: HTMLElement, el: HTMLElement, status: Map<string, string>): void {
    this.dispose();
    this.api = api; this.model = api.getModel(); this.host = host;
    this.mmOn = true;
    const model = this.model;
    const mm = (this.mm = createMiniMap(el, api.viewport, () => model, {
      placement: 'top-left', offset: 0, width: 242, height: 128, padding: 70, showLinks: true,
      panelBackground: 'transparent', panelBorder: 'transparent', ariaLabel: 'Workflow minimap',
      maskColor: 'rgba(59,82,217,0.06)', maskStroke: 'rgba(59,82,217,0.85)',
      nodeColor: (n: any) => RUN_COLOUR[status.get(n.id) ?? ''] ?? (DARK.matches ? '#646d82' : '#aab2c3'),
    }));
    mm.portal.element.style.borderRadius = '0';
    mm.portal.element.style.boxShadow = 'none';
    this.mmNotes = document.createElementNS(SVG, 'g');
    mm.element.insertBefore(this.mmNotes, mm.element.firstChild);
  }
  dispose(): void {
    cancelAnimationFrame(this.raf); this.raf = 0;
    try { this.mm?.dispose(); } catch { /* the canvas went first */ }
    this.mm = null;
  }
  /** Redraw the minimap's steps and notes (once per frame). */
  refresh(): void {
    if (this.raf || !this.mm) return;
    this.raf = requestAnimationFrame(() => {
      this.raf = 0;
      if (!this.mm) return;
      this.mm.refresh();
      this.mmNotes!.replaceChildren(...this.model.getGroups().filter((g: any) => g.getMetadata('note')).map((g: any) => {
        const f = g.getOuterBounds(), r = document.createElementNS(SVG, 'rect');
        for (const [k, v] of Object.entries({ x: f.x, y: f.y, width: f.width, height: f.height, rx: 10, fill: DARK.matches ? '#4a4120' : '#f8e7a6' })) r.setAttribute(k, String(v));
        return r;
      }));
    });
  }
  /** The camera moved: the readout and the slider follow its zoom. */
  zoomed(zoom: number): void {
    const pct = Math.round(zoom * 100);
    if (pct !== this.zoomPct) { this.zoomPct = pct; this.changed(); }
  }
  private flash(which: 'fit' | 'fitw'): void {
    this.flashing = which; this.changed();
    setTimeout(() => { if (this.flashing === which) { this.flashing = null; this.changed(); } }, 260);
  }
  private contentBounds(): { x: number; y: number; width: number; height: number } | null {
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const n of this.model.getNodes()) {
      if (!n.data?.action) continue;
      const b = visualBox({ ...geomOf(n.data), x: n.position.x, y: n.position.y });
      x0 = Math.min(x0, b.x0); y0 = Math.min(y0, b.y0); x1 = Math.max(x1, b.x1); y1 = Math.max(y1, b.y1);
    }
    for (const g of this.model.getGroups()) { const f = g.getOuterBounds(); x0 = Math.min(x0, f.x); y0 = Math.min(y0, f.y); x1 = Math.max(x1, f.x + f.width); y1 = Math.max(y1, f.y + f.height); }
    return Number.isFinite(x0) ? { x: x0, y: y0, width: x1 - x0, height: y1 - y0 } : null;
  }
  /** Fit everything in view (at most 125%). */
  frame(): void {
    const b = this.contentBounds(), r = this.host.getBoundingClientRect(), vp = this.api.viewport;
    if (!b) return;
    const z = Math.min(1.25, (r.width - 80) / b.width, (r.height - 80) / b.height);
    vp.setZoom(z);
    const c = vp.getViewport();
    vp.setViewport({ ...c, x: b.x + b.width / 2 - c.width / 2, y: b.y + b.height / 2 - c.height / 2 });
    this.api.renderNow();
  }
  /** The card's Fit. */
  fit(): void { this.flash('fit'); this.frame(); }
  /** The card's Fit width. */
  fitWidth(): void {
    this.flash('fitw');
    const b = this.contentBounds(), r = this.host.getBoundingClientRect(), vp = this.api.viewport;
    if (!b) return;
    const z = vp.setZoom(Math.min(2, (r.width - 48) / b.width));
    // Centred when it fits the height too, else its top edge just under the canvas top.
    const c = vp.getViewport(), cy = b.height * z <= r.height - 48 ? b.y + b.height / 2 : b.y - 24 / z + r.height / z / 2;
    vp.setViewport({ ...c, x: b.x + b.width / 2 - c.width / 2, y: cy - c.height / 2 });
    this.api.renderNow();
  }
  /** The zoom slider (percent). */
  zoomTo(pct: number): void { this.api.viewport.setZoom(pct / 100); this.api.renderNow(); }
  /** Show or hide the minimap. */
  toggleMinimap(): void {
    this.mmOn = !this.mmOn;
    this.changed();
    if (this.mmOn) this.refresh();
  }
}

// Workflow automation builder — the sticky notes. A note is an engine GROUP
// (its members ride along when it is dragged); this draws it on a div UNDER
// the diagram's SVG that copies viewport.getHtmlLayerTransform(), keeps its
// frame round its members (its header measured in a hidden twin), and leaves
// the frame alone while a step is being dragged — the engine decides on drop,
// by that frame, whether the step left or joined the note.
//
// Framework-free: the same file sits next to the workflow-builder demo in the
// React, Vue, Angular and Qwik apps.
import { visualBox, noteFrame, LAYOUT } from './workflow-builder-layout';
import { geomOf, esc } from './workflow-builder-steps';

export interface NoteData { title: string; text: string }

export class NoteLayer {
  private api: any = null;
  private model: any = null;
  private layer: HTMLElement | null = null;
  private twin: HTMLElement | null = null;
  private headers = new Map<string, number>();

  /** Put the layer under the diagram of `api` (first child of its root). */
  mount(api: any, diagramRoot: HTMLElement): void {
    this.unmount();
    this.api = api; this.model = api.getModel();
    this.headers.clear();
    this.layer = document.createElement('div');
    this.layer.className = 'wf-notes';
    diagramRoot.insertBefore(this.layer, diagramRoot.firstChild);
    if (!this.twin || !this.twin.isConnected) {
      this.twin = document.createElement('div');
      this.twin.id = 'wf-measure';
      this.twin.style.cssText = 'position:absolute;left:-10000px;top:0;visibility:hidden;pointer-events:none';
      document.body.appendChild(this.twin);
    }
  }
  unmount(): void { this.layer?.remove(); this.layer = null; }
  /** Unmount and drop the measuring twin too. */
  dispose(): void { this.unmount(); this.twin?.remove(); this.twin = null; }

  /** The height a note's title + text take above its steps (measured once per text). */
  header(nt: NoteData): number {
    const key = `${nt.title}\u0000${nt.text}`;
    if (!this.headers.has(key)) {
      const mh = this.twin!;
      mh.innerHTML = `<div class="wf-note" style="width:${LAYOUT.minNoteWidth}px"><div class="wf-note-h">${esc(nt.title)}</div><div class="wf-note-t">${esc(nt.text)}</div></div>`;
      const h = (mh.firstChild as HTMLElement).getBoundingClientRect().height;
      this.headers.set(key, Math.ceil(h + 6));
    }
    return this.headers.get(key)!;
  }

  /** Fit every note's frame round its members (not mid-drag), then redraw; `selId` is the selected note. */
  fit(selId: string | null): void {
    const model = this.model;
    const dragging = this.api.getDraggingNodeIds?.().length > 0;
    for (const g of model.getGroups()) {
      const nt = g.getMetadata('note');
      if (!nt || dragging) continue;
      const boxes = [...g.members].map((id) => model.getNode(id)).filter((n: any) => n?.data?.action)
        .map((n: any) => visualBox({ ...geomOf(n.data), x: n.position.x, y: n.position.y }));
      const f = noteFrame(boxes, this.header(nt));
      if (!f) continue;
      const o = g.getOuterBounds();
      if (Math.abs(o.x - f.x) > 0.5 || Math.abs(o.y - f.y) > 0.5 || Math.abs(o.width - f.width) > 0.5 || Math.abs(o.height - f.height) > 0.5) g.setFrame(f);
    }
    this.render(selId);
  }

  /** The camera moved: the layer follows it. */
  follow(): void { if (this.layer) this.layer.style.transform = this.api.viewport.getHtmlLayerTransform(); }

  /** Draw every note at its frame; `selId` is the selected note. */
  render(selId: string | null): void {
    const layer = this.layer;
    if (!layer) return;
    this.follow();
    const seen = new Set<string>();
    for (const g of this.model.getGroups().filter((x: any) => x.getMetadata('note'))) {
      seen.add(g.id);
      let el = layer.querySelector(`[data-note="${CSS.escape(g.id)}"]`) as HTMLElement | null;
      if (!el) {
        el = document.createElement('div');
        el.className = 'wf-note';
        el.dataset['note'] = g.id;
        el.innerHTML = '<div class="wf-note-h"></div><div class="wf-note-t"></div>';
        layer.appendChild(el);
      }
      const f = g.getOuterBounds(), nt = g.getMetadata('note');
      Object.assign(el.style, { left: f.x + 'px', top: f.y + 'px', width: f.width + 'px', height: f.height + 'px' });
      el.firstChild!.textContent = nt.title;
      el.lastChild!.textContent = nt.text;
      el.classList.toggle('sel', selId === g.id);
    }
    for (const el of Array.from(layer.children) as HTMLElement[]) if (!seen.has(el.dataset['note']!)) el.remove();
  }
}

interaction/marketing-automation.text:
/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * The marketing automation studio's behaviour — translated line for line from
 * the setup() of demos/interaction/marketing-automation.html, so the React,
 * Vue, Angular and Qwik versions share ONE copy instead of four drifting ones.
 *
 * This controller owns the engine side: the computed layout and its animated
 * re-flow, the cards, lines and branch chips, the world-space "+" buttons, the
 * snapshot history on the engine's own CommandManager, the keyboard, the card
 * pan, the navigator's minimap, and the Test flow's token, ticks and clock.
 * The framework file owns the chrome — the top bar, the property panel, the
 * step menu, the dialogs, the toast and the navigator's controls — and renders
 * it from `MaUi`, a fresh plain object handed over through `onChange(ui)` on
 * every change.
 *
 * The library workarounds the JS page needs are kept here, each where it bites:
 * a keydown listener registered BEFORE the diagram (hookKeys) owns Delete;
 * edge ids encode both endpoints, so an edge id never changes endpoints; a
 * port that moved is removed and re-added under the same id; resizing is
 * switched off after every setNodes; a straight line gets a collinear midpoint
 * as a manual waypoint so the router never detours it; chip label fractions
 * are recomputed every frame; an undo awaits the last commandManager.execute;
 * the minimap is standalone, refreshed from model events, moved into the card.
 *
 * (Copied verbatim next to the demo in each app — keep the copies identical.)
 */
import { Command, PortModel } from '@grafloria/engine';
import { createMiniMap, createViewportPortal } from '@grafloria/element';
import * as M from './marketing-automation-model';
import type { Automation, Box, Contact, Kind, LayoutEdge, Layout, Pt, RunEvent, RunPlan, Slot, Step } from './marketing-automation-model';
import {
  injectIconCss, ico, esc, lineStyle, chipStyle, cardContent, noteContent, measure, disposeMeasure,
  portsFor, FIELDS, SUBTITLE, type FieldDef, type PortSpec,
} from './marketing-automation-view';

const { G, KINDS } = M;
const STORE_KEY = 'grafloria.marketing-automation.v1';
const NOTE = 'note';
const darkQuery = () => matchMedia('(prefers-color-scheme: dark)');
const reduced = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

// ---- the diagram's options (the JS page's render() call) -----------------------
export const MIN_ZOOM = 0.2;
export const MAX_ZOOM = 2;
export const INTERACTION = {
  portVisibility: 'hidden', enableLinkReconnection: false, showLinkEndpointHandles: false, enableWaypointEditing: false,
  enableControlPointEditing: false, enableInPlaceTextEdit: false, enableSmartAutoConnect: false, enableProximityConnect: false,
};
// Branch paths SHARE their horizontal run under the Branch on purpose —
// nudging them onto separate lanes would undo the fan-out.
export const RENDERER = { channelNudging: false, parallelLinks: false };
/** The same three, as one render() options object (Angular's <grafloria-diagram>). */
export const RENDER_OPTIONS = { minZoom: MIN_ZOOM, maxZoom: MAX_ZOOM, interaction: INTERACTION, renderer: RENDERER };

// ---- what the chrome paints: plain data, safe for any framework's store --------
export interface MenuItemUi { key: string; label: string; desc: string; icon: string; tone: string; search: string; hidden: boolean; active: boolean }
export interface MenuGroupUi { group: string; hidden: boolean; items: MenuItemUi[] }
export interface MenuUi { mode: 'steps' | 'criteria'; placeholder: string; q: string; groups: MenuGroupUi[]; empty: boolean; left: number; top: number }
export interface PickUi { armId: string; label: string; sub: string }
export type DialogUi =
  | { kind: 'delete'; stepId: string; title: string; text: string; picks: PickUi[]; allLabel: string }
  | { kind: 'new' }
  | { kind: 'test'; picked: string; contacts: Contact[] };
export interface FieldUi {
  key: string; label: string; type: 'select' | 'text' | 'number' | 'textarea'; value: string;
  options: Array<[string, string]>; min?: number; placeholder?: string; hint: string;
}
export interface ArmUi { id: string; label: string; isDefault: boolean; value: string; options: Array<[string, string]>; removable: boolean }
export interface LogRowUi { n: number; kind: string; icon: string; tone: string; clock: string; text: string }
export type PanelUi =
  | { view: 'none'; rev: number }
  | { view: 'overview'; rev: number; steps: number; paths: number; wait: string; description: FieldUi }
  | {
      view: 'step'; rev: number; stepId: string; tone: string; icon: string; name: string; sub: string; sec: string;
      fields: FieldUi[]; delay: { amount: string; unit: string } | null; arms: ArmUi[] | null; del: string | null;
    }
  | { view: 'run'; rev: number; contact: Contact; clock: string; state: string; done: boolean; log: LogRowUi[] };
export interface MaUi {
  /** The automation's name in the top bar. */
  title: string;
  status: string;
  live: boolean;
  canUndo: boolean;
  canRedo: boolean;
  /** The zoom, in percent (the navigator's slider and readout). */
  zoom: number;
  mapShown: boolean;
  menu: MenuUi | null;
  dialog: DialogUi | null;
  toast: string | null;
  /** `rev` changes whenever the JS page would re-render the panel's HTML. */
  panel: PanelUi;
}
export function initialUi(): MaUi {
  return { title: '', status: 'Draft', live: false, canUndo: false, canRedo: false, zoom: 100, mapShown: true,
    menu: null, dialog: null, toast: null, panel: { view: 'none', rev: 0 } };
}
export const DELAY_UNITS = M.DELAY_UNITS;

interface Plus {
  key: string; portal: any; btn: HTMLButtonElement; x: number; y: number;
  kind?: 'insert' | 'add'; slot?: Slot; edge?: LayoutEdge; anchor?: string; branchId?: string;
}
interface MenuDef { key: string; label: string; desc: string; icon: string; tone: string; search: string }
interface MenuCtx {
  mode: 'steps' | 'criteria'; anchorEl: HTMLElement; slot?: Slot; at?: Pt;
  groups: Array<{ group: string; list: MenuDef[] }>; q: string; active: string | null; left: number; top: number;
}
interface Run {
  token: number; active: boolean; status: Record<string, string>; wait: Record<string, string>; links: Record<string, string>;
  arms: Set<string>; path: string[]; contact: Contact | null; plan: RunPlan | null; ticks: number; speed: number; log: RunEvent[];
  clock: number; state: { text: string; done: boolean }; tokenAt?: { x: number; y: number; edge: string };
}
const freshRun = (): Run => ({ token: 0, active: false, status: {}, wait: {}, links: {}, arms: new Set(), path: [], contact: null, plan: null,
  ticks: 0, speed: 1, log: [], clock: 9 * 60, state: { text: 'Running…', done: false } });
const LOG_ICON: Record<string, [string, string]> = { trigger: ['flag', 'indigo'], end: ['check', 'green'] };
const UNIT: Record<string, number> = { minutes: 1, hours: 60, days: 1440, weeks: 10080 };

/** Every edit is ONE snapshot command on the engine's own stack. */
class SnapshotCommand extends Command {
  private fresh = true;
  constructor(private owner: MarketingAutomation, name: string, readonly before: Automation, readonly after: Automation) { super(name); }
  execute(): void { if (this.fresh) { this.fresh = false; return; } this.owner.applySnapshot(this.after); }
  undo(): void { this.owner.applySnapshot(this.before); }
  redo(): void { this.owner.applySnapshot(this.after); }
  serialize() { return { id: this.id, name: this.name, timestamp: this.timestamp, data: { before: this.before, after: this.after } }; }
}

export class MarketingAutomation {
  /** The chrome's state as of the last change. */
  ui: MaUi = initialUi();
  /** Called with a fresh `MaUi` on every change; set by the framework. */
  onChange: (ui: MaUi) => void = () => {};

  // ---- engine side -------------------------------------------------------------
  private api: any = null;
  private model: any = null;
  private engine: any = null;
  private cm: any = null;
  private stage!: HTMLElement;   // #stage — the top bar, #canvas and #ma-panel
  private host!: HTMLElement;    // #canvas — the diagram and the chrome over it
  private htmlLayer!: HTMLElement;
  private offs: Array<() => void> = [];
  private gen = 0;               // every init/teardown bumps it; older async work stops

  // ---- the automation and its drawing -----------------------------------------------
  private state: Automation = M.sampleAutomation();
  private noteCollapsed = false;
  private L: Layout | null = null;           // the last computed layout
  private cur: Record<string, Box> = {};     // id → box as drawn right now (mid-animation too)
  private target: Record<string, Box> = {};  // id → box where the layout wants it
  private tween: { raf: number } | null = null;
  private fresh = new Set<string>();         // cards that just appeared (a short fade-in)
  private idleWaiters: Array<() => void> = [];
  private pluses = new Map<string, Plus>();
  private lastExec: Promise<unknown> = Promise.resolve();
  private live: { name: string; before: Automation } | null = null;
  private published = false;
  private statusText = 'Draft';
  private statusLive = false;
  private selectedId: string | null = null;
  private testView = false;
  private panelRev = 0;
  private panelCache: { key: string; ui: PanelUi } | null = null;
  private menuCtx: MenuCtx | null = null;
  private dialog: DialogUi | null = null;
  private toastText: string | null = null;
  private toastTimer: any = 0;
  private cardPan: { x: number; y: number; moving: boolean } | null = null;
  private panned = false;
  private mini: any = null;
  private miniQueued = false;
  private mapShown = true;
  private zoomPct = 100;
  private RUN: Run = freshRun();
  private tokenPortal: any = null;
  private lastTick: any = null;
  private panJob = 0;
  private pickedContact = M.CONTACTS[0].id;

  private box = (id: string): Box => this.cur[id] || this.target[id];
  private heightOf = (s: Step): number => (s.kind === 'trigger' ? measure(cardContent(s), G.TRIGGER_W) : G.CARD_H);
  private $ = (id: string): HTMLElement | null => this.stage?.querySelector(`#${id}`) ?? null;

  // ---- keyboard: registered BEFORE the diagram -----------------------------------
  /**
   * A key event dispatched on window itself runs its listeners in REGISTRATION
   * order (capture or not), and the engine's own Delete must never run before
   * the tree has had its say — so the framework calls this before the diagram
   * mounts. Returns the unhook.
   */
  hookKeys(): () => void {
    const on = (e: KeyboardEvent) => this.onKey(e);
    window.addEventListener('keydown', on, true);
    return () => window.removeEventListener('keydown', on, true);
  }

  /** Mount on a fresh instance: `stage` holds the top bar, #canvas and #ma-panel. Safe to call again. */
  init(instance: any, stage: HTMLElement): Promise<void> {
    this.teardown();
    const gen = this.gen;
    injectIconCss();
    this.api = instance;
    this.model = instance.getModel();
    this.engine = instance.getEngine();
    this.cm = this.engine.commandManager;
    this.stage = stage;
    this.host = stage.querySelector('#canvas') as HTMLElement;
    this.state = M.sampleAutomation();
    this.noteCollapsed = false;
    this.L = null; this.cur = {}; this.target = {}; this.tween = null;
    this.fresh.clear(); this.pluses.clear(); this.idleWaiters = [];
    this.lastExec = Promise.resolve(); this.live = null;
    this.published = false; this.statusText = 'Draft'; this.statusLive = false;
    this.selectedId = null; this.testView = false; this.menuCtx = null; this.dialog = null; this.toastText = null; this.panelCache = null;
    this.RUN = freshRun(); this.lastTick = null; this.pickedContact = M.CONTACTS[0].id;
    const api = instance, model = this.model, host = this.host;

    // The run animates lines — battery saver must not still them.
    api.animations.updateConfig({ respectBatteryStatus: false, batterySavingMode: false });
    // A builder keeps its words at every zoom: widen every LOD tier to draw everything.
    try {
      const cfg = model.getLODConfig();
      const all = new Set<unknown>();
      for (const t of cfg.tiers) for (const f of t.features) all.add(f);
      for (const t of cfg.tiers) for (const f of all) t.features.add(f);
      model.setLODConfig(cfg);
    } catch { /* an engine without LOD config draws everything anyway */ }
    this.htmlLayer = host.querySelector('.grafloria-html-layer') as HTMLElement;

    // ---- the chrome over the canvas keeps its pointer, wheel and double-click ----
    const stop = (e: Event) => e.stopPropagation();
    for (const el of Array.from(host.querySelectorAll('.ma-nav, #ma-menu, #ma-dialog, #ma-toast'))) {
      for (const t of ['pointerdown', 'mousedown', 'wheel', 'dblclick']) {
        el.addEventListener(t, stop);
        this.offs.push(() => el.removeEventListener(t, stop));
      }
    }

    // ---- history: the toolbar follows the engine's stack ---------------------------
    for (const ev of ['command:executed', 'command:undone', 'command:redone', 'command:history-cleared']) {
      this.track(this.engine.eventBus.on(ev, () => setTimeout(() => { if (gen === this.gen) this.refreshUndo(); }, 0)));
    }

    // ---- selection drives the panel -----------------------------------------------
    this.track(api.on('selection:change', ({ nodes }: any) => {
      const id = nodes.length === 1 && this.state.steps[nodes[0].id] ? nodes[0].id : null;
      if (id === this.selectedId) return;
      this.commitLive();
      this.selectedId = id;
      if (!this.testView) this.renderPanel();
    }));

    // The step menu closes on any press outside it (and its "+").
    this.listen(document, 'pointerdown', (e: Event) => {
      const menu = this.$('ma-menu'), t = e.target as Node;
      if (this.menuCtx && menu && !menu.contains(t) && !this.menuCtx.anchorEl.contains(t)) this.closeMenu();
    }, true);

    // The layout owns where cards go, so a drag that starts ON a card pans the
    // canvas (a drag on empty canvas already does).
    this.listen(host, 'pointerdown', (e: Event) => {
      const pe = e as PointerEvent;
      this.panned = false;
      if (pe.button !== 0 || !(pe.target instanceof Element)) return;
      const g = pe.target.closest('[data-node-id]');
      this.cardPan = g && g.closest('svg.grafloria-diagram') ? { x: pe.clientX, y: pe.clientY, moving: false } : null;
    });
    this.listen(window, 'pointermove', (e: Event) => {
      const pe = e as PointerEvent, cp = this.cardPan;
      if (!cp) return;
      if (!(pe.buttons & 1)) { this.cardPan = null; return; }
      if (!cp.moving && Math.hypot(pe.clientX - cp.x, pe.clientY - cp.y) < 5) return;
      cp.moving = this.panned = true;
      api.viewport.panByScreenDelta(cp.x - pe.clientX, cp.y - pe.clientY);
      cp.x = pe.clientX; cp.y = pe.clientY;
      api.renderNow();
    });
    this.listen(window, 'pointerup', () => { this.cardPan = null; });

    // Clicks inside cards: the trigger's chip × and "Add criteria", the note's chevron.
    this.listen(host, 'click', (e: Event) => {
      const t = e.target;
      if (!(t instanceof Element) || this.panned) return;
      const x = t.closest('.ma-chip-x');
      if (x) {
        const key = Array.from(x.classList).find((c) => c.startsWith('ma-x-'))?.slice(5);
        if (key && M.CRITERIA[key]) this.edit(`Remove criterion: ${M.CRITERIA[key].label}`, (s) => { s.steps[s.rootId].props[key] = ''; });
        return;
      }
      const add = t.closest('.ma-addcrit') as HTMLElement | null;
      if (add) { this.openMenu('criteria', add, {}); return; }
      if (t.closest('.ma-note-head')) { this.noteCollapsed = !this.noteCollapsed; this.sync({ animate: true }); }
    });

    // ---- the navigator: a standalone minimap, moved into the card -------------------
    const dark = darkQuery().matches;
    const root = host.querySelector('.grafloria-diagram-root') as HTMLElement;
    const mini = createMiniMap(root, api.viewport, () => model, {
      placement: 'none', showLinks: true, padding: 60, ariaLabel: 'Minimap — click or drag to move the view',
      linkColor: dark ? 'rgba(150,160,185,.55)' : 'rgba(120,130,150,.6)',
      maskColor: dark ? 'rgba(139,156,242,.16)' : 'rgba(59,82,217,.1)', maskStroke: dark ? '#8b9cf2' : '#3b52d9',
      nodeColor: (n: any) => {
        const s = this.state.steps[n.id];
        if (n.id === NOTE) return dark ? '#343a64' : '#dfe3fb';
        if (!s) return 'transparent';
        if (this.RUN.status[n.id] === 'done') return dark ? '#3ccf7e' : '#7fd3a2';
        return s.kind === 'branch' ? (dark ? '#6a5321' : '#f0cf8e') : n.isSelected() ? '#3b52d9' : (dark ? '#4a5266' : '#c3cad8');
      },
    } as any);
    this.mini = mini;
    (host.querySelector('.ma-nav-mini') ?? host.querySelector('#ma-nav-map'))?.appendChild(mini.portal.element);
    const refreshMini = () => {
      if (this.miniQueued) return;
      this.miniQueued = true;
      requestAnimationFrame(() => { this.miniQueued = false; if (gen === this.gen) mini.refresh(); });
    };
    for (const ev of ['node:added', 'node:removed', 'node:changed', 'link:added', 'link:removed', 'selection:changed']) this.track(model.on(ev, refreshMini));
    this.track(api.viewport.onChange(() => this.showZoom()));
    // A narrow canvas (the gallery's side panels open) starts with the map folded.
    this.mapShown = host.getBoundingClientRect().width >= 720;

    // ---- the Test flow's token: a world-space portal that rides the lines -----------
    this.tokenPortal = createViewportPortal(this.htmlLayer, { className: 'ma-token-host' });
    this.tokenPortal.element.innerHTML = '<div class="ma-token"></div>';
    this.tokenPortal.element.style.pointerEvents = 'none';
    this.tokenPortal.element.hidden = true;

    // ---- the scheme can flip live: model styles follow it ------------------------------
    const mq = darkQuery();
    const onScheme = () => { if (this.L) this.sync({ animate: false }); };
    mq.addEventListener?.('change', onScheme);
    this.offs.push(() => mq.removeEventListener?.('change', onScheme));

    this.sync({ animate: false });
    this.showZoom(false);
    this.frameView();
    this.renderPanel();
    this.refreshUndo();
    return new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(() => r())));
  }

  /** Unmount: listeners off, the run stopped, the portals and the measuring twin gone. */
  destroy(): void {
    this.teardown();
    this.api = null;
    disposeMeasure();
  }

  private teardown(): void {
    this.gen++;
    for (const off of this.offs.splice(0)) { try { off(); } catch { /* already gone */ } }
    cancelAnimationFrame(this.tween?.raf ?? 0);
    this.tween = null;
    this.RUN.token++;
    this.panJob++;
    clearTimeout(this.toastTimer);
    for (const p of this.pluses.values()) { try { p.portal.dispose(); } catch { /* the layer went with the diagram */ } }
    this.pluses.clear();
    try { this.tokenPortal?.dispose(); } catch { /* idem */ }
    try { this.lastTick?.dispose(); } catch { /* idem */ }
    try { this.mini?.dispose(); } catch { /* idem */ }
    this.tokenPortal = null; this.lastTick = null; this.mini = null;
  }
  private track(off: unknown): void { if (typeof off === 'function') this.offs.push(off as () => void); }
  private listen(target: EventTarget, type: string, fn: (e: Event) => void, capture = false): void {
    target.addEventListener(type, fn, capture);
    this.offs.push(() => target.removeEventListener(type, fn, capture));
  }
  /** Run `fn` once the framework has painted what `ready()` waits for (a few frames at most). */
  private whenReady(ready: () => boolean, fn: () => void, tries = 90): void {
    const gen = this.gen;
    const tick = (n: number) => {
      if (gen !== this.gen) return;
      if (ready()) fn();
      else if (n > 0) requestAnimationFrame(() => tick(n - 1));
    };
    tick(tries);
  }
  /** Run `fn` once the panel shows its latest render. */
  private afterPanel(fn: (panel: HTMLElement) => void): void {
    const want = String(this.panelRev);
    this.whenReady(() => this.$('ma-panel')?.querySelector('.ma-p-head')?.getAttribute('data-rev') === want, () => fn(this.$('ma-panel')!));
  }

  // ---- what the chrome paints ------------------------------------------------------
  private emit(): void {
    if (!this.api) return;
    this.ui = {
      title: this.state.title,
      status: this.statusText,
      live: this.statusLive,
      canUndo: !!this.cm?.canUndo(),
      canRedo: !!this.cm?.canRedo(),
      zoom: this.zoomPct,
      mapShown: this.mapShown,
      menu: this.menuCtx ? this.menuUi(this.menuCtx) : null,
      dialog: this.dialog,
      toast: this.toastText,
      panel: this.panelUi(),
    };
    this.onChange(this.ui);
  }
  private toast(text: string): void {
    this.toastText = text;
    this.emit();
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => { this.toastText = null; this.emit(); }, 2600);
  }

  // ---- layout + the animated re-flow -------------------------------------------------
  /** The note sits left of the trigger, clear of everything on the rows it spans. */
  private placeNote(lay: Layout): Box {
    const state = this.state;
    const h = measure(noteContent(state, this.noteCollapsed), G.NOTE_W);
    const trig = lay.boxes[state.rootId];
    const y0 = trig.y - 6, y1 = y0 + h;
    let minX = trig.x;
    const span = (top: number, bottom: number) => bottom > y0 - 24 && top < y1 + 24;
    for (const b of Object.values(lay.boxes)) if (span(b.y, b.y + b.h)) minX = Math.min(minX, b.x);
    for (const e of lay.edges) {
      const pts = M.routeOf(e, (id) => lay.boxes[id]);
      for (let i = 1; i < pts.length; i++) {
        const a = pts[i - 1], c = pts[i];
        if (span(Math.min(a.y, c.y), Math.max(a.y, c.y))) minX = Math.min(minX, a.x, c.x);
      }
      if (e.kind === 'arm') { const m = M.armMarks(e, (id) => lay.boxes[id]); if (span(m.chip.y - 12, m.chip.y + 12)) minX = Math.min(minX, m.chip.x - 60); }
    }
    return { x: minX - G.NOTE_GAP - G.NOTE_W, y: y0, w: G.NOTE_W, h };
  }

  private nodeSpec(id: string, b: Box, pos: { x: number; y: number }): any {
    const s = this.state.steps[id];
    const base = { id, position: { x: pos.x, y: pos.y }, size: { width: b.w, height: b.h }, draggable: false };
    if (s) {
      return { ...base, selectable: true, shape: { type: 'rect', cornerRadius: 12 }, style: { selection: 'border' },
        metadata: { html: { content: cardContent(s, this.RUN.status[id], { fresh: this.fresh.has(id), wait: this.RUN.wait[id] }), padding: 0, interactive: s.kind === 'trigger' } },
        ports: portsFor(id, s.kind, b.w, b.h) };
    }
    if (id === NOTE) {
      return { ...base, selectable: false, shape: { type: 'rect', cornerRadius: 14 },
        metadata: { html: { content: noteContent(this.state, this.noteCollapsed), padding: 0, interactive: true } }, ports: [] };
    }
    return { ...base, selectable: false, shape: { type: 'rect', cornerRadius: 12 }, ports: portsFor(id, 'anchor', b.w, b.h) };
  }
  // Ports are built once per node; a card that changed height re-seats its
  // ports under the SAME ids, so its lines stay attached.
  private seatPorts(node: any, specs: PortSpec[]): void {
    for (const p of specs) {
      const have = node.getPort(p.id);
      const a = have?.layout?.args;
      if (have && a && a.x === p.layout.args.x && a.y === p.layout.args.y) continue;
      if (have) node.removePort(p.id);
      node.addPort(new PortModel({ id: p.id, type: p.type, side: p.side, shape: p.shape, layout: p.layout, isConnectableStart: false, isConnectableEnd: false } as any));
    }
  }
  private classesFor(id: string): string[] {
    const s = this.state.steps[id];
    if (s) return ['ma-n', `ma-n-${s.kind}`, ...(this.RUN.status[id] ? [`ma-s-${this.RUN.status[id]}`] : [])];
    return id === NOTE ? ['ma-n-note'] : ['ma-n-anchor'];
  }
  private setClasses(node: any, want: string[]): void {
    const have = [...(node.classes || [])];
    if (have.join(' ') !== want.join(' ')) node.setClasses(want);
  }

  /**
   * Draw the state: lay the tree out, reconcile the model's nodes and lines
   * (setNodes / setEdges), then glide everything to its new place.
   */
  private sync(opts: { animate?: boolean; spawn?: Pt } = {}): void {
    const api = this.api, model = this.model, state = this.state;
    const L = (this.L = M.computeLayout(state, this.heightOf));
    const noteBox = this.placeNote(L);
    const target = (this.target = { ...L.boxes, [NOTE]: noteBox });
    const order = [...M.orderedIds(state).filter((id) => id !== state.rootId), ...L.anchors.map((a) => a.id), NOTE, state.rootId];
    const animate = !!opts.animate && !reduced();
    const startOf = (id: string): { x: number; y: number } => {
      if (animate && this.cur[id]) return this.cur[id];
      const t = target[id];
      if (animate && opts.spawn && state.steps[id]) return { x: opts.spawn.x - t.w / 2, y: opts.spawn.y - t.h / 2 };
      return t;
    };
    const gen = this.gen;
    for (const id of order) {
      if (!model.getNode(id) && state.steps[id] && animate) {
        this.fresh.add(id);
        setTimeout(() => { if (gen !== this.gen) return; this.fresh.delete(id); this.paintStep(id); }, 420);
      }
    }
    const specs = order.map((id) => this.nodeSpec(id, target[id], startOf(id)));
    api.setNodes(specs);
    specs.forEach((sp) => {
      const n = model.getNode(sp.id);
      if (!n) return;
      n.behavior.resizable = false;   // the layout sizes the cards
      this.seatPorts(n, sp.ports);
      this.setClasses(n, this.classesFor(sp.id));
    });
    api.setEdges(L.edges.map((e) => ({ id: e.id, source: e.from, target: e.to,
      sourceHandle: e.kind === 'add' ? `${e.from}__add` : `${e.from}__out`, targetHandle: `${e.to}__in`,
      type: 'orthogonal', style: lineStyle(e.kind, this.RUN.links[e.id]) })));
    this.syncPluses();
    const next: Record<string, Box> = {};
    for (const id of order) next[id] = { ...startOf(id), w: target[id].w, h: target[id].h };
    this.cur = next;
    if (animate) this.tweenTo();
    else { cancelAnimationFrame(this.tween?.raf ?? 0); this.tween = null; this.cur = { ...target }; this.frame(); for (const r of this.idleWaiters.splice(0)) r(); }
    this.refreshUndo();
  }

  private tweenTo(): void {
    cancelAnimationFrame(this.tween?.raf ?? 0);
    const from: Record<string, Pt> = {};
    for (const [id, b] of Object.entries(this.cur)) from[id] = { x: b.x, y: b.y };
    const t0 = performance.now(), dur = 320;
    const me = (this.tween = { raf: 0 });
    const step = (now: number) => {
      if (this.tween !== me) return;
      const k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 3);
      for (const [id, to] of Object.entries(this.target)) {
        const f = from[id] || to;
        this.cur[id] = { x: f.x + (to.x - f.x) * e, y: f.y + (to.y - f.y) * e, w: to.w, h: to.h };
      }
      try { this.frame(); } finally {
        if (k < 1) me.raf = requestAnimationFrame(step);
        else { this.tween = null; for (const r of this.idleWaiters.splice(0)) r(); }
      }
    };
    step(t0);
  }
  /** Resolves once the re-flow animation (if any) has landed. */
  idle(): Promise<void> { return this.tween ? new Promise((r) => this.idleWaiters.push(r)) : Promise.resolve(); }

  /** One frame: nodes to their drawn boxes; lines, chips, "+" and the note follow. */
  private frame(): void {
    const model = this.model, L = this.L!;
    for (const [id, b] of Object.entries(this.cur)) {
      const n = model.getNode(id);
      if (n && (n.position.x !== b.x || n.position.y !== b.y)) n.setPosition(b.x, b.y);
    }
    for (const e of L.edges) {
      const link = model.getLink(e.id);
      if (!link) continue;
      const pts = M.routeOf(e, this.box);
      // Always an explicit route: a bare two-point line would go to the
      // obstacle router, which happily detours a dashed stub round its own card.
      const drawn = pts.length > 2 ? pts : [pts[0], { x: (pts[0].x + pts[1].x) / 2, y: (pts[0].y + pts[1].y) / 2 }, pts[1]];
      link.setPoints(drawn);
      link.setMetadata('hasManualWaypoints', true);
      if (e.kind === 'arm') {
        const m = M.armMarks(e, this.box);
        link.setLabels([{ id: 'chip', text: e.label, position: M.fractionAt(pts, m.chip), offset: { x: 0, y: 0 }, style: chipStyle(this.RUN.arms.has(e.id)) }]);
      }
    }
    for (const p of this.pluses.values()) this.placePlus(p);
    this.api.renderNow();
  }

  // ---- the "+" buttons: world-space portals, keyed by the slot they insert at --
  private syncPluses(): void {
    const L = this.L!;
    const slotKey = (slot: Slot) => `${slot.parentId}|${slot.armId || ''}`;
    const want = new Map<string, Partial<Plus>>();
    for (const e of L.edges) {
      if (e.kind === 'spine') want.set(slotKey(e.slot!), { kind: 'insert', slot: e.slot, edge: e });
      else if (e.kind === 'arm' && !e.toEnd) want.set(slotKey(e.slot!), { kind: 'insert', slot: e.slot, edge: e });
    }
    for (const a of L.anchors) {
      if (a.role === 'end') want.set(slotKey(a.slot!), { kind: 'insert', slot: a.slot, anchor: a.id });
      else want.set(`add|${a.branchId}`, { kind: 'add', branchId: a.branchId, anchor: a.id });
    }
    for (const [key, p] of this.pluses) if (!want.has(key)) { p.portal.dispose(); this.pluses.delete(key); }
    for (const [key, w] of want) {
      let p = this.pluses.get(key);
      if (!p) {
        const portal = createViewportPortal(this.htmlLayer, { className: 'ma-plus-host' });
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'ma-plus';
        btn.innerHTML = ico('plus');
        // It opens a picker (or adds a path) for whatever slot it holds NOW.
        btn.setAttribute('data-gate-inert', '');
        portal.element.appendChild(btn);
        for (const t of ['pointerdown', 'mousedown', 'dblclick']) portal.element.addEventListener(t, (ev: Event) => ev.stopPropagation());
        const made: Plus = { key, portal, btn, x: 0, y: 0 };
        btn.addEventListener('click', () => this.onPlus(made));
        this.pluses.set(key, made);
        p = made;
      }
      // A slot can change shape (an empty path's end "+" becomes a line's "+"):
      // drop what the last layout said before taking this one's word for it.
      p.anchor = undefined; p.edge = undefined; p.slot = undefined; p.branchId = undefined;
      Object.assign(p, w);
      p.btn.classList.toggle('add', w.kind === 'add');
      p.btn.dataset['slot'] = key;
      const label = w.kind === 'add' ? 'Add another path to this Branch' : 'Insert a step here';
      p.btn.title = label;
      p.btn.setAttribute('aria-label', label);
    }
  }
  private placePlus(p: Plus): void {
    let pt: Pt | null;
    if (p.anchor) { const b = this.box(p.anchor); if (!b) return; pt = { x: b.x + b.w / 2, y: b.y + b.h / 2 }; }
    else if (p.edge!.kind === 'arm') pt = M.armMarks(p.edge!, this.box).plus;
    else { const a = this.box(p.edge!.from), b = this.box(p.edge!.to); pt = { x: b.x + b.w / 2, y: (a.y + a.h + b.y) / 2 }; }
    if (!pt) return;
    p.x = pt.x; p.y = pt.y;
    p.portal.setPosition(pt.x - 11, pt.y - 11);
  }

  // ---- history: every edit is ONE snapshot command on the engine's stack ------
  /** Put a snapshot back (an undo, a redo). */
  applySnapshot(snap: Automation): void {
    this.state = M.clone(snap);
    this.stopRun(true);
    this.sync({ animate: true });
    this.markDirty();
    this.renderPanel();
  }
  private record(name: string, before: Automation): boolean {
    const after = M.clone(this.state);
    if (JSON.stringify(after) === JSON.stringify(before)) return false;
    this.markDirty();
    this.lastExec = Promise.resolve(this.cm.execute(new SnapshotCommand(this, name, before, after))).catch(() => {});
    return true;
  }
  // The command lands on the stack a few microtasks after execute() is called;
  // an undo pressed right after an edit must wait for it, or it would undo the
  // edit BEFORE that one.
  private async undoRedo(redo: boolean): Promise<void> {
    this.commitLive();
    await this.lastExec;
    await (redo ? this.engine.redo() : this.engine.undo());
    this.refreshUndo();
  }
  undo(): void { void this.undoRedo(false); }
  redo(): void { void this.undoRedo(true); }
  /** Mutate the state as ONE undoable edit, then re-flow. */
  private edit<T>(name: string, mutate: (s: Automation) => T, syncOpts: { spawn?: Pt } = {}): T {
    this.commitLive();
    const before = M.clone(this.state);
    const result = mutate(this.state);
    if (this.record(name, before)) { this.stopRun(true); this.sync({ animate: true, ...syncOpts }); this.renderPanel(); }
    return result;
  }
  private refreshUndo(): void { this.emit(); }

  // Live edits (typing in the panel) paint the card as you type and land in the
  // history as one step when the field is committed (blur / Enter / a pick).
  private liveEdit(name: string, mutate: (s: Automation) => void): void {
    if (!this.live) this.live = { name, before: M.clone(this.state) };
    mutate(this.state);
    this.stopRun(true);
    this.sync({ animate: false });
  }
  /** Land the field being typed in as one history step (blur / Enter / a pick). */
  commitLive(): void {
    if (!this.live) return;
    const { name, before } = this.live;
    this.live = null;
    this.record(name, before);
  }
  private markDirty(): void {
    this.statusText = this.published ? 'Unpublished changes' : 'Draft';
    this.statusLive = false;
  }

  // ---- selection drives the panel ---------------------------------------------
  private select(id: string | null): void {
    const model = this.model;
    model.clearSelection?.();
    const n = id && model.getNode(id);
    if (n) model.selectNode(n);
    this.selectedId = n ? id : null;
    this.api.renderNow();
    if (!this.testView) this.renderPanel();
  }
  private renderPanel(): void { this.panelRev++; this.emit(); }

  // ---- the step menu (the "+" and "Add criteria") -------------------------------
  private openMenu(mode: 'steps' | 'criteria', anchorEl: HTMLElement, mctx: { slot?: Slot; at?: Pt }): void {
    this.closeMenu();
    const root = this.state.steps[this.state.rootId];
    const groups = mode === 'criteria'
      ? [{ group: 'Add criteria', list: Object.entries(M.CRITERIA).filter(([k]) => { const v = root.props[k]; return v === '' || v == null; })
          .map(([k, c]) => ({ key: k, label: c.label, desc: 'Only enroll contacts that match', icon: 'flag', tone: 'indigo' })) }]
      : M.MENU_GROUPS.map((g) => ({ group: g, list: (Object.entries(KINDS) as Array<[Kind, M.KindInfo]>).filter(([, k]) => k.group === g)
          .map(([key, k]) => ({ key, label: k.label, desc: k.desc!, icon: k.icon, tone: k.tone })) }));
    const withSearch = groups.map((g) => ({ group: g.group, list: g.list.map((it) => ({ ...it, search: (it.label + ' ' + it.desc + ' ' + g.group).toLowerCase() })) }));
    const ctx: MenuCtx = { mode, ...mctx, anchorEl, groups: withSearch, q: '', active: null, left: -10000, top: 0 };
    this.menuCtx = ctx;
    this.filterMenu();
    anchorEl.setAttribute('aria-expanded', 'true');
    this.emit();
    // Placed beside its anchor once the framework has painted it (its size decides).
    const count = withSearch.reduce((n, g) => n + g.list.length, 0);
    this.whenReady(() => { const m = this.$('ma-menu'); return !!m && !m.hidden && m.querySelectorAll('.ma-mi').length === count; }, () => {
      if (this.menuCtx !== ctx) return;
      const menu = this.$('ma-menu')!;
      const hr = this.host.getBoundingClientRect(), r = anchorEl.getBoundingClientRect();
      const mw = menu.offsetWidth, mh = menu.offsetHeight;
      let left = r.right - hr.left + 10;
      const top = r.top - hr.top - 18;
      if (left + mw > hr.width - 10) left = r.left - hr.left - mw - 10;
      ctx.left = Math.max(10, left);
      ctx.top = Math.max(10, Math.min(top, hr.height - mh - 10));
      menu.style.left = ctx.left + 'px';
      menu.style.top = ctx.top + 'px';
      this.emit();
      (this.$('ma-menu-q') as HTMLInputElement | null)?.focus({ preventScroll: true });
    });
  }
  closeMenu(): void {
    if (!this.menuCtx) return;
    this.menuCtx.anchorEl.removeAttribute('aria-expanded');
    this.menuCtx = null;
    this.emit();
  }
  private visibleMenuKeys(ctx: MenuCtx): string[] {
    const q = ctx.q.trim().toLowerCase();
    return ctx.groups.flatMap((g) => g.list.filter((it) => !q || it.search.includes(q)).map((it) => it.key));
  }
  private filterMenu(): void {
    const ctx = this.menuCtx;
    if (ctx) ctx.active = this.visibleMenuKeys(ctx)[0] ?? null;
  }
  private menuUi(ctx: MenuCtx): MenuUi {
    const q = ctx.q.trim().toLowerCase();
    const groups = ctx.groups.map((g) => {
      const items = g.list.map((it) => ({ ...it, hidden: !!q && !it.search.includes(q), active: it.key === ctx.active }));
      return { group: g.group, hidden: items.every((i) => i.hidden), items };
    });
    return { mode: ctx.mode, placeholder: ctx.mode === 'criteria' ? 'Search criteria…' : 'Search steps…', q: ctx.q, groups,
      empty: groups.every((g) => g.hidden), left: ctx.left, top: ctx.top };
  }
  /** The menu's search box was typed in. */
  setMenuQuery(q: string): void {
    if (!this.menuCtx) return;
    this.menuCtx.q = q;
    this.filterMenu();
    this.emit();
  }
  /** ↑ / ↓ walk the visible steps, Enter picks, Escape closes (the search box's keydown). */
  menuKey(e: { key: string; preventDefault(): void }): void {
    const ctx = this.menuCtx;
    if (!ctx) return;
    const vis = this.visibleMenuKeys(ctx);
    const at = ctx.active ? vis.indexOf(ctx.active) : -1;
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (!vis.length) return;
      ctx.active = vis[(at + (e.key === 'ArrowDown' ? 1 : -1) + vis.length) % vis.length];
      this.emit();
      const key = ctx.active;
      this.whenReady(() => !!this.$('ma-menu')?.querySelector(`.ma-mi.active[data-key="${key}"]`),
        () => this.$('ma-menu')?.querySelector('.ma-mi.active')?.scrollIntoView({ block: 'nearest' }));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (vis[at]) this.pickMenu(vis[at]);
    } else if (e.key === 'Escape') { e.preventDefault(); this.closeMenu(); }
  }
  /** A step (or a criterion) was picked in the menu. */
  pickMenu(key: string): void {
    const m = this.menuCtx;
    if (!m) return;
    this.closeMenu();
    if (m.mode === 'criteria') {
      this.edit(`Add criterion: ${M.CRITERIA[key].label}`, (s) => { s.steps[s.rootId].props[key] = M.CRITERIA[key].fallback; });
      this.select(this.state.rootId);
      this.afterPanel((panel) => (panel.querySelector(`[data-k="${key}"]`) as HTMLElement | null)?.focus());
      return;
    }
    if (!M.slotExists(this.state, m.slot!)) return;
    const id = this.edit(`Insert ${KINDS[key as Kind].label}`, (s) => M.insertStep(s, m.slot!, key as Kind), { spawn: m.at });
    if (id) this.select(id);
  }
  private onPlus(p: Plus): void {
    if (p.kind === 'add') {
      const armId = this.edit('Add a path', (s) => M.addArm(s, p.branchId!));
      this.select(p.branchId!);
      this.afterPanel((panel) => (panel.querySelector(`input[data-arm="${armId}"]`) as HTMLInputElement | null)?.select());
      return;
    }
    if (this.menuCtx && this.menuCtx.anchorEl === p.btn) { this.closeMenu(); return; }
    this.openMenu('steps', p.btn, { slot: p.slot, at: { x: p.x, y: p.y } });
  }

  // ---- dialogs -------------------------------------------------------------------
  private openDialog(d: DialogUi): void {
    this.dialog = d;
    this.emit();
    this.whenReady(() => { const el = this.$('ma-dialog'); return !!el && !el.hidden && el.querySelector('.ma-dlg')?.getAttribute('data-kind') === d.kind; },
      () => (this.$('ma-dialog')?.querySelector('[data-focus]') as HTMLElement | null)?.focus({ preventScroll: true }));
  }
  closeDialog(): void { if (!this.dialog) return; this.dialog = null; this.emit(); }
  /** A button in the open dialog: `act` is its data-act, `arg` the path / contact it names. */
  dialogAct(act: string, arg?: string): void {
    const d = this.dialog;
    if (!d) return;
    if (d.kind === 'delete') {
      if (act === 'cancel') { this.closeDialog(); return; }
      if (act === 'keep' || act === 'all') {
        this.closeDialog();
        const keep = act === 'keep' ? arg ?? null : null;
        this.edit(keep ? 'Delete Branch (keep a path)' : 'Delete Branch and its paths', (st) => M.deleteStep(st, d.stepId, keep));
        this.select(null);
      }
    } else if (d.kind === 'new') {
      this.closeDialog();
      if (act === 'new') this.startNew();
    } else if (d.kind === 'test') {
      if (act === 'cancel') this.closeDialog();
      else if (act === 'pick' && arg) { this.pickedContact = arg; this.dialog = { ...d, picked: arg }; this.emit(); }
      else if (act === 'run') { this.closeDialog(); void this.runTest(M.CONTACTS.find((c) => c.id === this.pickedContact)!); }
    }
  }

  // ---- delete --------------------------------------------------------------------
  private requestDelete(id: string): void {
    const state = this.state, s = state.steps[id];
    if (!s) return;
    if (s.kind === 'trigger') { this.toast('The trigger starts the automation — press New to start over.'); return; }
    if (s.kind !== 'branch') {
      this.edit(`Delete ${KINDS[s.kind].label}`, (st) => M.deleteStep(st, id));
      this.select(null);
      return;
    }
    const below = M.subtreeIds(state, id).length - 1;
    this.openDialog({
      kind: 'delete', stepId: id, title: s.title,
      text: `This Branch has ${s.arms!.length} paths and ${below} step${below === 1 ? '' : 's'} below it. Keep one path in its place, or delete everything below.`,
      picks: s.arms!.map((a) => {
        const n = M.subtreeIds(state, a.next).length;
        return { armId: a.id, label: a.label, sub: n ? `${n} step${n === 1 ? ' moves' : 's move'} up into its place` : 'an empty path' };
      }),
      allLabel: below ? `Delete it and the ${below} step${below === 1 ? '' : 's'} below` : 'Delete the Branch',
    });
  }

  // Keyboard: Delete / Backspace remove the selected step. Undo / Redo stay with
  // the engine's own binding (they reach the same command stack). Copy, paste,
  // cut and duplicate are refused: the layout owns where steps go.
  private onKey(e: KeyboardEvent): void {
    if (!this.api) return;
    const t = e.target;
    if (t instanceof Element && !!t.closest('input, textarea, select, [contenteditable=""], [contenteditable="true"]')) return;
    if (e.key === 'Escape') { if (this.menuCtx) this.closeMenu(); if (this.dialog) this.closeDialog(); return; }
    if (e.key === 'Delete' || e.key === 'Backspace') {
      // Never the engine's own delete: the tree decides what a delete means.
      e.preventDefault();
      e.stopImmediatePropagation();
      if (this.dialog) return;
      const ids = this.model.getSelectedNodes().map((n: any) => n.id).filter((id: string) => this.state.steps[id]);
      if (ids.length === 1) this.requestDelete(ids[0]);
      else if (ids.length > 1) this.toast('Select one step to delete it.');
      return;
    }
    if ((e.ctrlKey || e.metaKey) && ['c', 'v', 'x', 'd'].includes(e.key.toLowerCase())) e.stopImmediatePropagation();
    // ⌘Z / Ctrl+Z, ⇧⌘Z / Ctrl+Shift+Z, Ctrl+Y: the same engine undo stack the
    // engine's own binding drives — taken here so a just-made edit lands first.
    if ((e.ctrlKey || e.metaKey) && ['z', 'y'].includes(e.key.toLowerCase())) {
      e.preventDefault();
      e.stopImmediatePropagation();
      void this.undoRedo(e.key.toLowerCase() === 'y' || e.shiftKey);
    }
  }

  // ---- the property panel ---------------------------------------------------------
  private longestWait(id: string | null, acc = 0): number {
    let best = acc;
    while (id) {
      const s: Step = this.state.steps[id];
      if (s.kind === 'delay') acc += (Number(s.props['amount']) || 0) * (UNIT[s.props['unit']] || 1440);
      best = Math.max(best, acc);
      if (s.kind === 'branch') { for (const a of s.arms!) best = Math.max(best, this.longestWait(a.next, acc)); break; }
      id = s.next;
    }
    return best;
  }
  /**
   * The panel as of its last render. Like the JS page's innerHTML, a form's
   * field values are written when the panel renders (`rev`), never while you
   * type — only its header line, and the test run's log and clock, are live.
   */
  private panelUi(): PanelUi {
    const RUN = this.RUN;
    if (this.testView && RUN.contact) return this.computePanel();
    const key = `${this.panelRev}|${this.selectedId ?? ''}`;
    if (this.panelCache?.key !== key) this.panelCache = { key, ui: this.computePanel() };
    const ui = this.panelCache.ui;
    if (ui.view !== 'step') return ui;
    const s = this.state.steps[ui.stepId];
    return s ? { ...ui, sec: s.kind === 'trigger' ? (M.TRIGGER_EVENTS[s.props['event']] || 'Trigger') : M.stepTitle(s) } : ui;
  }
  private computePanel(): PanelUi {
    const rev = this.panelRev, state = this.state, RUN = this.RUN;
    const field = (f: FieldDef, v: unknown): FieldUi => ({
      key: f.key, label: f.label, type: f.type, value: v == null ? '' : String(v),
      options: (f.options || []).map((o) => (Array.isArray(o) ? [String(o[0]), String(o[1])] : [String(o), String(o)]) as [string, string]),
      min: f.min, placeholder: f.placeholder, hint: f.hint,
    });
    if (this.testView && RUN.contact) {
      return { view: 'run', rev, contact: RUN.contact, clock: M.clockText(RUN.clock), state: RUN.state.text, done: RUN.state.done,
        log: RUN.log.map((ev, n) => {
          const [icon, tone] = LOG_ICON[ev.kind] || [KINDS[ev.kind as Kind].icon, KINDS[ev.kind as Kind].tone];
          return { n, kind: ev.kind, icon, tone, clock: M.clockText(ev.clock), text: ev.text };
        }) };
    }
    const s = this.selectedId ? state.steps[this.selectedId] : null;
    if (!s) {
      const steps = Object.keys(state.steps).length - 1;
      // Paths = the ends a contact can reach (every path ends in a "+").
      const ends = (id: string | null): number => {
        while (id) { const st: Step = state.steps[id]; if (st.kind === 'branch') return st.arms!.reduce((n, a) => n + ends(a.next), 0); id = st.next; }
        return 1;
      };
      const wait = this.longestWait(state.rootId);
      const waitText = !wait ? '—' : wait >= 1440 ? `${Math.round(wait / 144) / 10} d` : wait >= 60 ? `${Math.round(wait / 6) / 10} h` : `${wait} min`;
      return { view: 'overview', rev, steps, paths: ends(state.rootId), wait: waitText,
        description: field({ key: 'description', label: 'What it does', type: 'textarea', hint: 'Shown in the workflow description on the canvas.' }, state.description) };
    }
    const k = KINDS[s.kind];
    const fields: FieldUi[] = [];
    if (k.named) fields.push(field({ key: 'title', label: s.kind === 'branch' ? 'Question' : 'Step name', type: 'text', hint: 'Shown as the title on the card.' }, s.title));
    if (s.kind !== 'delay') for (const f of FIELDS[s.kind] || []) fields.push(field(f, s.props[f.key]));
    let arms: ArmUi[] | null = null;
    if (s.kind === 'branch') {
      const prop = M.BRANCH_PROPS[s.props['property']];
      arms = s.arms!.map((a) => ({
        id: a.id, label: a.label, isDefault: !!a.isDefault, value: a.value, removable: s.arms!.length > 1,
        options: [...(prop?.values || []), ...(prop?.values.some(([v]) => v === a.value) ? [] : [[a.value, a.value] as [string, string]])],
      }));
    }
    return {
      view: 'step', rev, stepId: s.id, tone: k.tone, icon: k.icon,
      name: s.kind === 'trigger' ? 'Trigger' : k.label, sub: SUBTITLE[s.kind],
      sec: s.kind === 'trigger' ? (M.TRIGGER_EVENTS[s.props['event']] || 'Trigger') : M.stepTitle(s),
      fields, arms,
      delay: s.kind === 'delay' ? { amount: String(s.props['amount'] ?? ''), unit: String(s.props['unit']) } : null,
      del: s.kind !== 'trigger' ? `Delete ${s.kind === 'branch' ? 'Branch' : 'step'}` : null,
    };
  }

  private editName(s: Step, key: string): string {
    return key === 'title' ? `Rename ${KINDS[s.kind].label}` : key === 'description' ? 'Edit description' : `Edit ${KINDS[s.kind].label}`;
  }
  /**
   * A field in the panel changed: `committed` is false while typing (an
   * `input` event) and true when it is committed (a `change` event).
   */
  panelInput(target: EventTarget | null, committed: boolean): void {
    const t = target as HTMLInputElement | null;
    if (!t || !(t instanceof Element) || !this.api) return;
    const stepId = (t.closest('[data-step]') as HTMLElement | null)?.dataset['step'];
    const s = stepId ? this.state.steps[stepId] : null;
    const k = t.dataset['k'], armId = t.dataset['arm'];
    if (k === 'description' && !s) {
      this.liveEdit('Edit description', (st) => { st.description = t.value; });
    } else if (s && k === 'property') {
      if (!committed) return;      // a structural pick: one step, then the rows redraw
      this.edit('Change what the Branch splits on', (st) => M.setBranchProperty(st, s.id, t.value));
      return;
    } else if (s && k) {
      const v: any = t.type === 'number' ? (t.value === '' ? '' : Number(t.value)) : t.value;
      if (k === 'amount' && s.kind === 'delay' && (v === '' || v < 1)) return;
      this.liveEdit(this.editName(s, k), (st) => { if (k === 'title') st.steps[s.id].title = v; else st.steps[s.id].props[k] = v; });
    } else if (s && armId) {
      const ak = t.dataset['ak'] as 'label' | 'value';
      this.liveEdit('Edit a path', (st) => { const a = st.steps[s.id].arms!.find((x) => x.id === armId); if (a) a[ak] = t.value; });
      if (ak === 'value' && committed) {
        // Picking a value names the path after it, unless it was renamed by hand.
        const b = this.state.steps[s.id];
        const a = b.arms!.find((x) => x.id === armId);
        const prop = M.BRANCH_PROPS[b.props['property']];
        const lab = prop?.values.find(([v]) => v === t.value)?.[1];
        const inp = this.$('ma-panel')?.querySelector(`input[data-arm="${armId}"]`) as HTMLInputElement | null;
        if (a && lab && inp && prop.values.some(([, l]) => l === a.label)) { this.liveEdit('Edit a path', () => { a.label = lab; }); inp.value = lab; }
      }
    } else return;
    if (committed) this.commitLive();
  }
  /** A button in the panel: `act` is its data-act, `arm` the path it names. */
  panelAct(act: string, arm?: string): void {
    const s = this.selectedId ? this.state.steps[this.selectedId] : null;
    if (act === 'delete' && s) this.requestDelete(s.id);
    else if (act === 'add-arm' && s) {
      const armId = this.edit('Add a path', (st) => M.addArm(st, s.id));
      this.afterPanel((panel) => (panel.querySelector(`input[data-arm="${armId}"]`) as HTMLInputElement | null)?.select());
    }
    else if (act === 'rm-arm' && s && arm) this.edit('Remove a path', (st) => M.removeArm(st, s.id, arm));
    else if (act === 'run-again' && this.RUN.contact) void this.runTest(this.RUN.contact);
    else if (act === 'run-pick') this.openTestDialog();
    else if (act === 'run-exit') this.exitTest();
  }
  /** The automation's name, typed in the top bar. */
  renameTitle(value: string): void { this.liveEdit('Rename the automation', (st) => { st.title = value; }); }

  // ---- Save / Load / New / Publish ---------------------------------------------------
  save(): void {
    this.commitLive();
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify({ format: 'grafloria-marketing-automation', version: 1, savedAt: new Date().toISOString(), automation: this.state }));
      this.toast(`Saved “${this.state.title}” in this browser.`);
    } catch { this.toast('This browser refused to save (private mode?).'); }
  }
  load(): boolean {
    this.commitLive();
    let saved: any = null;
    try { saved = JSON.parse(localStorage.getItem(STORE_KEY) || 'null'); } catch { saved = null; }
    if (!saved || !M.isAutomation(saved.automation)) { this.toast('Nothing saved yet — press Save first.'); return false; }
    const before = M.clone(this.state);
    this.state = M.clone(saved.automation);
    this.record('Load the saved automation', before);
    this.stopRun(true);
    this.sync({ animate: true });
    this.select(null);
    const at = new Date(saved.savedAt);
    this.toast(`Loaded the version saved at ${at.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}.`);
    return true;
  }
  private startNew(): void {
    this.commitLive();
    const before = M.clone(this.state);
    this.state = M.blankAutomation();
    this.record('New automation', before);
    this.stopRun(true);
    this.exitTest(false);
    this.select(null);
    this.sync({ animate: false });
    this.frameView();
    this.toast('Started over from a trigger — Undo brings the last one back.');
  }
  /** New: asks first (Undo brings the old one back). */
  askNew(): void { this.openDialog({ kind: 'new' }); }
  publish(): void {
    this.commitLive();
    this.published = true;
    this.statusText = 'Live';
    this.statusLive = true;
    this.toast(`Published — ${Object.keys(this.state.steps).length - 1} steps are live for new contacts.`);
  }

  // ---- the navigator: minimap + fit + zoom ---------------------------------------------
  private showZoom(emit = true): void {
    const z = Math.round(this.api.viewport.getZoom() * 100);
    if (z === this.zoomPct) return;
    this.zoomPct = z;
    if (emit) this.emit();
  }
  /** The zoom slider moved (percent). */
  setZoom(pct: number): void { this.api.viewport.setZoom(pct / 100); this.api.renderNow(); }
  toggleMap(): void {
    this.mapShown = !this.mapShown;
    this.emit();
    if (this.mapShown) this.whenReady(() => this.$('ma-nav-map')?.hidden === false, () => this.mini?.refresh());
  }
  contentBounds(): { x: number; y: number; width: number; height: number } {
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const b of Object.values(this.target)) { x0 = Math.min(x0, b.x); y0 = Math.min(y0, b.y); x1 = Math.max(x1, b.x + b.w); y1 = Math.max(y1, b.y + b.h); }
    return { x: x0, y: y0, width: x1 - x0, height: y1 - y0 };
  }
  /** Put world (wx, wy) at the canvas centre at zoom z. */
  private centerView(wx: number, wy: number, z?: number): void {
    const vp = this.api.viewport;
    if (z) vp.setZoom(z);
    const v = vp.getViewport();
    vp.setViewport({ x: wx - v.width / 2, y: wy - v.height / 2, width: v.width, height: v.height });
    this.api.renderNow();
  }
  fitAll(): void { const b = this.contentBounds(); this.api.viewport.fitToBounds(b, 40, { maxZoom: 1 }); this.api.renderNow(); }
  fitWidth(maxZ = 1, minZ = 0.2): void {
    const b = this.contentBounds(), v = this.api.viewport.getViewport();
    const z = Math.max(minZ, Math.min(maxZ, (v.width - 60) / b.width));
    this.centerView(b.x + b.width / 2, b.y - 28 / z + v.height / z / 2, z);
  }
  // First look: the width of the flow from the top, never tiny — and when it
  // cannot all fit, the spine (trigger first) stays in the middle.
  private frameView(): void {
    this.fitWidth(0.95, 0.5);
    const b = this.contentBounds(), v = this.api.viewport.getViewport(), z = this.api.viewport.getZoom();
    if (b.width * z > v.width - 40) {
      const t = this.target[this.state.rootId];
      this.centerView(t.x + t.w / 2, b.y - 28 / z + v.height / z / 2, z);
    }
  }

  // ---- Test flow: plan the contact's run, then animate it ---------------------------------
  private paintStep(id: string): void {
    const s = this.state.steps[id], n = this.model.getNode(id);
    if (!s || !n) return;
    n.setMetadata('html', { content: cardContent(s, this.RUN.status[id], { fresh: this.fresh.has(id), wait: this.RUN.wait[id] }), padding: 0, interactive: s.kind === 'trigger' });
    this.setClasses(n, this.classesFor(id));
  }
  private markLink(id: string, mark: string | null): void {
    if (mark) this.RUN.links[id] = mark; else delete this.RUN.links[id];
    const e = this.L?.edges.find((x) => x.id === id), link = this.model.getLink(id);
    if (e && link) link.updateStyle(lineStyle(e.kind, mark ?? undefined));
  }
  /** Clear the last run's marks (a new run, an edit, leaving the test). */
  private stopRun(clearMarks: boolean): void {
    const RUN = this.RUN;
    RUN.token++;
    if (RUN.active) this.setRunState('Stopped — the flow changed', false);
    RUN.active = false;
    if (this.tokenPortal) this.tokenPortal.element.hidden = true;
    if (!clearMarks) return;
    const had = Object.keys(RUN.status).length || Object.keys(RUN.links).length;
    RUN.status = {}; RUN.wait = {}; RUN.arms.clear();
    for (const id of Object.keys(RUN.links)) this.markLink(id, null);
    RUN.links = {};
    if (had) { for (const id of Object.keys(this.state.steps)) this.paintStep(id); if (this.L) this.frame(); }
    if (had && !RUN.active && RUN.state.done) this.setRunState('Out of date — the flow changed', false);
  }
  private setRunState(text: string, done: boolean): void {
    this.RUN.state = { text, done };
    this.emit();
  }
  private setStatus(id: string, st: string | null, wait?: string): void {
    if (st) this.RUN.status[id] = st; else delete this.RUN.status[id];
    if (wait) this.RUN.wait[id] = wait; else delete this.RUN.wait[id];
    this.paintStep(id);
    this.api.renderNow();
  }
  /** Pan (animated) until a card is inside the free part of the canvas. */
  private reveal(id: string): void {
    const b = this.box(id);
    if (!b) return;
    const api = this.api, vp = api.viewport, vb = vp.getViewBox(), z = vp.getZoom();
    const m = 40 / z;
    const navH = 190 / z;
    if (b.x >= vb.x + m && b.x + b.w <= vb.x + vb.width - m && b.y >= vb.y + m && b.y + b.h <= vb.y + vb.height - navH) return;
    const from = vp.getViewport();
    const dx = (b.x + b.w / 2) - (vb.x + vb.width / 2), dy = (b.y + b.h / 2) - (vb.y + vb.height * 0.42);
    const t0 = performance.now(), dur = reduced() || this.RUN.speed < 0.2 ? 0 : 380, job = ++this.panJob;
    const f = (now: number) => {
      if (job !== this.panJob) return;
      const k = dur ? Math.min(1, (now - t0) / dur) : 1, e = 1 - Math.pow(1 - k, 3);
      vp.setViewport({ ...from, x: from.x + dx * e, y: from.y + dy * e });
      api.renderNow();
      if (k < 1) requestAnimationFrame(f);
    };
    requestAnimationFrame(f);
  }
  private travel(edgeId: string, my: number): Promise<void> {
    const RUN = this.RUN;
    const e = this.L?.edges.find((x) => x.id === edgeId);
    if (!e) return Promise.resolve();
    this.markLink(edgeId, 'run');
    this.tokenPortal.element.hidden = false;
    const len = M.polyLength(M.routeOf(e, this.box));
    const dur = Math.max(260, Math.min(950, len * 2.4)) * RUN.speed;
    return new Promise((resolve) => {
      const t0 = performance.now();
      const f = (now: number) => {
        if (my !== RUN.token || RUN !== this.RUN) return resolve();
        const k = dur ? Math.min(1, (now - t0) / dur) : 1;
        const p = M.pointAlong(M.routeOf(e, this.box), k);
        this.tokenPortal.setPosition(p.x - 7, p.y - 7);
        RUN.tokenAt = { x: p.x, y: p.y, edge: edgeId };
        if (k < 1) requestAnimationFrame(f);
        else { this.markLink(edgeId, 'done'); RUN.path.push(edgeId); resolve(); }
      };
      requestAnimationFrame(f);
    });
  }
  private showTick(id: string, text: string): void {
    const b = this.box(id);
    if (!b) return;
    try { this.lastTick?.dispose(); } catch { /* gone */ }
    const p = (this.lastTick = createViewportPortal(this.htmlLayer, { className: 'ma-tick-host' }));
    p.element.style.pointerEvents = 'none';
    p.element.innerHTML = `<div class="ma-tick">${ico('ff')}${esc(text)}</div>`;
    p.setPosition(b.x + b.w + 10, b.y + 14);
    this.RUN.ticks++;
    setTimeout(() => { try { p.dispose(); } catch { /* gone */ } if (this.lastTick === p) this.lastTick = null; }, reduced() ? 600 : 1150);
  }
  private logRow(ev: RunEvent): void {
    this.RUN.log.push(ev);
    this.emit();
    // The panel scrolls, never the page.
    const n = this.RUN.log.length;
    this.whenReady(() => (this.$('ma-log')?.children.length ?? 0) >= n, () => { const p = this.$('ma-panel'); if (p) p.scrollTop = p.scrollHeight; });
  }
  private async runTest(contact: Contact, opts: { holdAt?: string } = {}): Promise<Run> {
    this.commitLive();
    this.closeMenu();
    this.stopRun(true);
    const RUN = this.RUN;
    const my = ++RUN.token;
    RUN.active = true;
    RUN.contact = contact;
    RUN.path = []; RUN.log = []; RUN.ticks = 0; RUN.clock = 9 * 60;
    RUN.state = { text: 'Running…', done: false };
    RUN.plan = M.planRun(this.state, contact);
    this.testView = true;
    this.select(null);
    this.renderPanel();
    for (const ev of RUN.plan.events) {
      if (my !== RUN.token) return RUN;
      if (ev.via) { await this.travel(ev.via, my); if (my !== RUN.token) return RUN; }
      if (ev.kind === 'end') { this.tokenPortal.element.hidden = true; this.logRow(ev); break; }
      this.setStatus(ev.id, 'run');
      this.reveal(ev.id);
      RUN.clock = ev.clock;     // a delay fast-forwards the clock right away
      this.logRow(ev);
      if (ev.wait) {
        this.setStatus(ev.id, 'wait', ev.wait);
        this.showTick(ev.id, ev.wait);
        if (ev.id === opts.holdAt) return RUN;   // the camera's frame: hold right here
        await sleep(900 * RUN.speed);
      } else {
        if (ev.id === opts.holdAt) return RUN;
        await sleep(380 * RUN.speed);
      }
      if (my !== RUN.token) return RUN;
      if (ev.armId) { const ae = this.L!.edges.find((x) => x.from === ev.id && x.armId === ev.armId); if (ae) { RUN.arms.add(ae.id); this.frame(); } }
      this.setStatus(ev.id, ev.ok === false ? 'fail' : 'done');
    }
    if (my !== RUN.token) return RUN;
    RUN.active = false;
    this.tokenPortal.element.hidden = true;
    const steps = RUN.plan.events.filter((e) => e.kind !== 'trigger' && e.kind !== 'end').length;
    this.setRunState(RUN.plan.enrolled ? `Done · ${steps} step${steps === 1 ? '' : 's'}` : 'Not enrolled', true);
    return RUN;
  }
  private exitTest(repaint = true): void {
    this.stopRun(true);
    this.testView = false;
    this.RUN.contact = null; this.RUN.plan = null;
    if (repaint) this.renderPanel();
  }
  /** Test flow: pick a sample contact, then Run test. */
  openTestDialog(): void {
    this.commitLive();
    this.openDialog({ kind: 'test', picked: this.pickedContact, contacts: M.CONTACTS });
  }
}

// marketing-automation-model.ts — the framework-free half of the Marketing
// automation studio demo (demos/interaction/marketing-automation-model.js,
// translated to TypeScript line for line).
//
//   • the step catalogue (what a visitor can insert) and the sample automation
//   • the tree edits: insert at a slot, delete (children re-attach), add / remove
//     a branch path — all mutate a plain JSON state, so a snapshot of it IS the
//     undo history and the Save file
//   • the guided top-down layout: a tidy tree — steps stacked on one spine, a
//     Branch fanning its paths out in columns centred under it
//   • the Test flow planner: which path one sample contact takes, and the log
//
// Nothing here touches the DOM or the diagram engine; the page draws what this
// computes. (Copied verbatim next to the demo in the React, Vue, Angular and
// Qwik apps — keep the copies identical.)

/* eslint-disable @typescript-eslint/no-explicit-any */

export type Kind = 'trigger' | 'email' | 'slack' | 'task' | 'score' | 'audience' | 'webhook' | 'delay' | 'branch';
export interface Arm { id: string; label: string; value: string; next: string | null; isDefault?: boolean }
export interface Step {
  id: string;
  kind: Kind;
  title: string;
  props: Record<string, any>;
  next: string | null;
  arms?: Arm[];
}
export interface Automation {
  title: string;
  description: string;
  rootId: string;
  seq: number;
  steps: Record<string, Step>;
}
/** Where a step hangs: under `parentId`, and under a Branch on path `armId`. */
export interface Slot { parentId: string; armId: string | null }
export interface Box { x: number; y: number; w: number; h: number }
export interface LayoutEdge {
  id: string;
  kind: 'spine' | 'arm' | 'stub' | 'add';
  from: string;
  to: string;
  slot?: Slot;
  armId?: string;
  label?: string;
  toEnd?: boolean;
  branchId?: string;
}
export interface Anchor { id: string; role: 'end' | 'add'; slot?: Slot; branchId?: string }
export interface Layout {
  boxes: Record<string, Box>;
  anchors: Anchor[];
  edges: LayoutEdge[];
  extents: { L: number; R: number };
}
export interface Pt { x: number; y: number }
export interface Contact {
  id: string; name: string; initials: string; company: string; stage: string;
  replied: boolean; opened: boolean; size: string; country: string; score: number; utm: string; blurb: string;
}
export interface RunEvent {
  id: string;
  via: string | null;
  kind: Kind | 'end';
  clock: number;
  text: string;
  ok?: boolean;
  wait?: string;
  armId?: string | null;
}
export interface RunPlan { events: RunEvent[]; enrolled: boolean; contact: Contact }

export const clone = <T>(o: T): T => JSON.parse(JSON.stringify(o));

// ---- the catalogue ------------------------------------------------------------
// `group` is the section of the "+" menu; `named` means the card title is the
// visitor's own name for the step (Delay and Lead score titles are derived).
