const PEOPLE = ['Ava Thompson', 'Noah Patel', 'Mia Chen', 'Liam García', 'Zoe Okafor', 'Omar Haddad', 'Lena Novak', 'Kai Morita', 'Ines Duarte', 'Theo Laurent'];
const CITIES = ['Lisbon', 'Toronto', 'Cairo', 'Osaka', 'Austin', 'Leeds', 'Porto', 'Lyon', 'Accra', 'Perth'];
const COUNTRIES = ['PT', 'CA', 'EG', 'JP', 'US', 'GB', 'PT', 'FR', 'GH', 'AU'];
const STREETS = ['12 Harbour Road', '48 Elm Street', '3 Rue Cler', '7-2 Sakura Dori', '901 Congress Ave', '22 Mill Lane', '5 Rua Nova', '18 Quai Bon', '40 Ring Road', '9 Bay View'];
const PRODUCTS = ['Wireless earbuds', 'Paperback notebook', 'Desk lamp', 'Trail bottle', 'Ceramic mug', 'Canvas tote', 'Phone stand', 'Wool socks', 'Tea sampler', 'USB-C cable'];
const CATEGORIES = ['Audio', 'Stationery', 'Home', 'Outdoors', 'Kitchen', 'Bags', 'Gadgets', 'Apparel', 'Pantry', 'Cables'];
const STATUSES = ['paid', 'shipped', 'pending', 'delivered', 'refunded'];
const PROVIDERS = ['stripe', 'paypal', 'adyen', 'stripe', 'paypal'];
const AMOUNTS = [19.9, 54, 7.5, 129, 32.25, 64.8, 12, 89.99, 45.5, 23.4];

const hash = (s: string) => {
  let h = 2166136261;
  for (let k = 0; k < s.length; k++) h = Math.imul(h ^ s.charCodeAt(k), 16777619);
  h ^= h >>> 16; h = Math.imul(h, 0x85ebca6b); h ^= h >>> 13; h = Math.imul(h, 0xc2b2ae35); h ^= h >>> 16;   // avalanche: "…0" and "…1" land far apart
  return h >>> 0;
};
const slug = (s: string) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

type Value = string | number | boolean | null;

function sampleValue(t: Table, c: Column, i: number): Value {
  const n = c.name.toLowerCase(), tn = t.name.toLowerCase();
  const { base, args } = parseType(c.type);
  const person = PEOPLE[i % PEOPLE.length];
  if (base === 'uuid') return `${hash(t.name).toString(16).padStart(8, '0').slice(0, 8)}-${(hash(c.name) & 0xffff).toString(16).padStart(4, '0')}-4000-8000-${String(i + 1).padStart(12, '0')}`;
  if (INTEGERISH.has(base)) {
    if (c.pk) return i + 1;
    if (/qty|quantity|count/.test(n)) return 1 + (i % 3);
    if (/rating|score|stars/.test(n)) return 5 - (i % 3);
    if (/year/.test(n)) return 2020 + (i % 6);
    return (hash(t.name + c.name + i) % 90) + 10;
  }
  if (base === 'decimal' || base === 'numeric' || base === 'real' || base === 'float' || base === 'double') return AMOUNTS[(i + n.length) % AMOUNTS.length];
  if (base === 'boolean' || base === 'bool') return i % 3 !== 2;
  if (base === 'timestamp' || base === 'datetime' || base === 'timestamptz') return `2026-09-${String(10 + (i % 18)).padStart(2, '0')} ${String(9 + (i % 9)).padStart(2, '0')}:${String((i * 7) % 60).padStart(2, '0')}:00`;
  if (base === 'date') return `2026-09-${String(10 + (i % 18)).padStart(2, '0')}`;
  if (base === 'time') return `${String(9 + (i % 9)).padStart(2, '0')}:30:00`;
  if (base === 'json' || base === 'jsonb') return '{"source":"web"}';
  if (base === 'blob' || base === 'bytea') return null;
  // text-like: lean on the column name
  let s: string;
  if (/email/.test(n)) s = person.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z]+/g, '.') + '@example.com';
  else if (/phone|mobile/.test(n)) s = `+1 555 01${String(i).padStart(2, '0')}`;
  else if (/country/.test(n)) s = COUNTRIES[i % COUNTRIES.length];
  else if (/city|town/.test(n)) s = CITIES[i % CITIES.length];
  else if (/line|street|address/.test(n)) s = STREETS[i % STREETS.length];
  else if (/postal|zip|post_code/.test(n)) s = `${1000 + i * 37}-1${String(i).padStart(2, '0')}`;
  else if (/status|state/.test(n)) s = STATUSES[i % STATUSES.length];
  else if (/provider|gateway|method/.test(n)) s = PROVIDERS[i % PROVIDERS.length];
  else if (/sku|code/.test(n)) s = `SKU-${1001 + i}`;
  else if (/currency/.test(n)) s = ['USD', 'EUR', 'GBP'][i % 3];
  else if (/slug/.test(n)) s = slug((/categor/.test(tn) ? CATEGORIES : PRODUCTS)[i % 10]);
  else if (/url|link|website/.test(n)) s = `https://example.com/${slug(t.name)}/${i + 1}`;
  else if (/color|colour/.test(n)) s = ['teal', 'amber', 'slate', 'rose'][i % 4];
  else if (/(^|_)(full_)?name$|^title$|^label$/.test(n)) s = /categor|tag|group|team/.test(tn) ? CATEGORIES[i % 10] : /product|item|book|course/.test(tn) ? PRODUCTS[i % 10] : person;
  else if (/body|comment|note|description|text|bio|summary/.test(n)) s = ['Arrived quickly, works well.', 'Lovely quality.', 'Smaller than expected.', 'Would buy again.'][i % 4];
  else if (/role/.test(n)) s = ['owner', 'admin', 'member', 'viewer'][i % 4];
  else s = `${c.name} ${i + 1}`;
  if (base === 'char' && args[0]) s = String(s).padEnd(Number(args[0]), 'X').slice(0, Number(args[0]));
  else if (base === 'varchar' && args[0]) s = String(s).slice(0, Number(args[0]));
  return s;
}

function literal(v: Value | undefined, d: string): string {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'boolean') return d === 'postgresql' ? (v ? 'TRUE' : 'FALSE') : (v ? '1' : '0');
  if (typeof v === 'number') return String(v);
  return `'${String(v).replace(/'/g, "''")}'`;
}

/**
 * INSERT statements that fill every table with a few rows (more in tables that
 * point at others, so a GROUP BY has something to count). Foreign keys always
 * hold a value the referenced table really has; UNIQUE / PRIMARY KEY columns
 * never repeat. Returns { sql, rows }.
 */
export function seedSQL(schema: { tables: Table[]; rels: Rel[] }, d: string): { sql: string; rows: number } {
  const T = new Map(schema.tables.map((t) => [t.id, t]));
  const { order } = creationOrder(schema);
  const depthOf = new Map<string, number>();
  const depth = (tid: string, seen = new Set<string>()): number => {
    if (depthOf.has(tid)) return depthOf.get(tid)!;
    if (seen.has(tid)) return 0;
    seen.add(tid);
    let dd = 0;
    for (const r of schema.rels) if (r.from.t === tid && r.to.t !== tid && T.has(r.to.t)) dd = Math.max(dd, depth(r.to.t, seen) + 1);
    depthOf.set(tid, dd);
    return dd;
  };
  const values = new Map<string, Array<Record<string, Value>>>();   // tableId → [{ colId: value }]
  const q = (n: string) => quoteIdent(n, d);
  const out: string[] = [];
  let total = 0;
  for (const tid of order) {
    const t = T.get(tid)!;
    if (!t.columns.length) continue;
    const fks = schema.rels.filter((r) => r.from.t === tid && T.get(r.to.t)?.columns.some((c) => c.id === r.to.c));
    let n = Math.min(4 + 2 * depth(tid), 10);
    // A unique foreign key can use each parent row once.
    for (const r of fks) {
      const fc = t.columns.find((c) => c.id === r.from.c);
      const parentRows = r.to.t === tid ? n : (values.get(r.to.t)?.length ?? 0);
      if (fc && (fc.uq || fc.pk || r.card === '1:1') && parentRows) n = Math.min(n, parentRows);
    }
    const rows: Array<Record<string, Value>> = [];
    // A composite primary key is unique as a TUPLE, not per column — only a
    // single-column key (or a UNIQUE column) is kept from repeating.
    const singlePk = t.columns.filter((c) => c.pk).length === 1;
    const seen = new Map(t.columns.filter((c) => c.uq || (c.pk && singlePk)).map((c) => [c.id, new Set<string>()]));
    for (let i = 0; i < n; i++) {
      const row: Record<string, Value> = {};
      for (const c of t.columns) {
        const fk = fks.find((r) => r.from.c === c.id);
        let v: Value;
        if (fk) {
          const parent = fk.to.t === tid ? rows : (values.get(fk.to.t) ?? []);
          const unique = c.uq || c.pk || fk.card === '1:1';
          if (fk.to.t === tid) v = i === 0 ? null : parent[(i - 1) % parent.length]?.[fk.to.c] ?? null;   // self-reference: point at an earlier row
          else if (!parent.length) v = null;
          // A unique key uses each parent once; otherwise a skewed pick, so some
          // parents have several children and some none (a GROUP BY has a story).
          else v = parent[unique ? i % parent.length : Math.min(parent.length - 1, Math.floor(parent.length * Math.pow((hash(`${t.name}.${c.name}.${i}`) % 997) / 997, 1.15)))][fk.to.c];
          if (v === null && (c.nn || c.pk) && fk.to.t === tid) v = sampleValue(t, c, i);
        } else v = sampleValue(t, c, i);
        const set = seen.get(c.id);
        if (set && v !== null) {
          let k = 2;
          while (set.has(String(v))) v = typeof v === 'number' ? v + 1000 : `${String(v).replace(/-\d+$/, '')}-${k++}`;
          set.add(String(v));
        }
        row[c.id] = v;
      }
      rows.push(row);
    }
    values.set(tid, rows);
    total += rows.length;
    out.push(`INSERT INTO ${q(t.name)} (${t.columns.map((c) => q(c.name)).join(', ')}) VALUES\n` +
      rows.map((row) => '  (' + t.columns.map((c) => literal(row[c.id], d)).join(', ') + ')').join(',\n') + ';');
  }
  return { sql: out.join('\n\n'), rows: total };
}

// Real in-browser databases for the Data modeling studio's query runner —
// demos/diagrams/data-modeling-db.js, verbatim, with types. The React, Vue,
// Angular and Qwik versions each keep an identical copy next to their demo file.
//
// Nothing here loads with the page. The first Run on an engine downloads it:
//   SQLite      — sql.js 1.10.3 (SQLite compiled to WebAssembly), from cdnjs
//   PostgreSQL  — PGlite (Postgres compiled to WebAssembly), an ES module from jsDelivr
// MySQL has no in-browser build, so the runner offers the other two instead.
//
// Each run builds the schema from scratch, inserts the seed rows and runs the
// visitor's query, and reports which of those three steps failed, if one did.
/* eslint-disable @typescript-eslint/no-explicit-any */

const SQLJS_BASE = 'https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/';
const PGLITE_URL: string = 'https://cdn.jsdelivr.net/npm/@electric-sql/pglite@0.5.8/dist/index.js';

export type EngineKind = 'sqlite' | 'postgresql';
export const ENGINES: Record<EngineKind, { label: string; lib: string; size: string; host: string }> = {
  sqlite: { label: 'SQLite', lib: 'sql.js 1.10.3', size: 'about 1 MB', host: 'cdnjs' },
  postgresql: { label: 'PostgreSQL', lib: 'PGlite', size: 'about 3 MB', host: 'jsDelivr' },
};

/** A loaded engine: sql.js's module (`SQL`) or a PGlite database (`db`). */
export interface Engine { kind: EngineKind; version: string; SQL?: any; db?: any }
export interface RunResult { columns: string[]; rows: unknown[][]; ms: number; statements: number }

const loads: Partial<Record<string, Promise<Engine>>> = {};   // kind → Promise<engine>
const ready: Partial<Record<string, Engine>> = {};            // kind → engine, once loaded

const withTimeout = <T>(p: Promise<T>, ms: number, what: string): Promise<T> => Promise.race([
  p,
  new Promise<T>((_, rej) => setTimeout(() => rej(new Error(`${what} did not arrive within ${Math.round(ms / 1000)} s — check the network`)), ms)),
]);

function loadScript(src: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = src;
    s.async = true;
    s.onload = () => resolve();
    s.onerror = () => reject(new Error(`could not load ${src}`));
    document.head.appendChild(s);
  });
}

export const isLoaded = (kind: string) => !!ready[kind];

/** PGlite's FS bundle, fetched and read up front, in the Blob-like shape its `fsBundle` option takes. */
async function readFsBundle() {
  const buf = await (await fetch(new URL('pglite.data', PGLITE_URL))).arrayBuffer();
  return { arrayBuffer: () => ({ then: (ok: (b: ArrayBuffer) => void) => ok(buf) }) };
}

/** Load (once) and return the engine for `kind`: 'sqlite' | 'postgresql'. */
export function loadEngine(kind: EngineKind, timeoutMs = 60000): Promise<Engine> {
  if (loads[kind]) return loads[kind]!;
  let p: Promise<Engine>;
  if (kind === 'sqlite') {
    p = (async () => {
      const w = window as any;
      if (!w.initSqlJs) await loadScript(SQLJS_BASE + 'sql-wasm.js');
      const SQL = await w.initSqlJs({ locateFile: (file: string) => SQLJS_BASE + file });
      const probe = new SQL.Database();
      const version = probe.exec('select sqlite_version()')[0]?.values?.[0]?.[0] ?? '';
      probe.close();
      return { kind, version: `SQLite ${version}`, SQL };
    })();
  } else if (kind === 'postgresql') {
    p = (async () => {
      const mod = await import(/* @vite-ignore */ PGLITE_URL);
      // (Port note) Under zone.js — the Angular app — native Promise#then is
      // patched, and PGlite keeps its FS bundle from a then() callback it never
      // awaits: that callback then runs AFTER PGlite has started and asked for the
      // bundle (`undefined.byteLength`). There PGlite gets the bundle already read,
      // through a then() that answers at once. Elsewhere: exactly the JS page.
      const db = (window as any).Zone ? new mod.PGlite({ fsBundle: await readFsBundle() }) : new mod.PGlite();
      await db.waitReady;
      const v = await db.query('select version()');
      const version = String(Object.values(v.rows[0] ?? {})[0] ?? 'PostgreSQL').split(' on ')[0].split(',')[0];
      return { kind, version, db };
    })();
  } else {
    return Promise.reject(new Error(`no in-browser engine for ${kind}`));
  }
  loads[kind] = withTimeout(p, timeoutMs, `The ${ENGINES[kind].label} engine (${ENGINES[kind].lib})`)
    .then((e) => { ready[kind] = e; return e; })
    .catch((e) => { delete loads[kind]; throw e; });   // a failed load can be retried
  return loads[kind]!;
}

class StepError extends Error {
  phase: string;
  constructor(phase: string, cause: any) { super(cause && cause.message ? cause.message : String(cause)); this.phase = phase; }
}

const cell = (v: unknown) => (v instanceof Uint8Array ? `‹${v.length} bytes›` : v);

/**
 * Build `ddl`, insert `seed`, run `query` on a fresh database. Resolves to
 * { columns, rows, ms, statements } for the query's last result set, or
 * rejects with an Error whose `.phase` is 'schema' | 'seed' | 'query'.
 */
export async function runScript(engine: Engine, { ddl, seed, query }: { ddl: string; seed: string; query: string }): Promise<RunResult> {
  const t0 = performance.now();
  if (engine.kind === 'sqlite') {
    const db = new engine.SQL.Database();
    try {
      try { db.exec(ddl); } catch (e) { throw new StepError('schema', e); }
      try { if (seed.trim()) db.exec(seed); } catch (e) { throw new StepError('seed', e); }
      let res: any[];
      try { res = db.exec(query); } catch (e) { throw new StepError('query', e); }
      const last = res[res.length - 1];
      return {
        columns: last ? last.columns : [],
        rows: last ? last.values.map((r: unknown[]) => r.map(cell)) : [],
        ms: performance.now() - t0,
        statements: res.length,
      };
    } finally {
      db.close();
    }
  }
  // PostgreSQL: one long-lived PGlite, a fresh public schema per run.
  const db = engine.db;
  try { await db.exec('DROP SCHEMA IF EXISTS public CASCADE; CREATE SCHEMA public;'); } catch (e) { throw new StepError('schema', e); }
  try { await db.exec(ddl); } catch (e) { throw new StepError('schema', e); }
  try { if (seed.trim()) await db.exec(seed); } catch (e) { throw new StepError('seed', e); }
  let results: any[];
  try { results = await db.exec(query, { rowMode: 'array' }); } catch (e) { throw new StepError('query', e); }
  const last = [...results].reverse().find((r) => r.fields && r.fields.length) ?? results[results.length - 1];
  const columns: string[] = last?.fields?.map((f: any) => f.name) ?? [];
  const rows = (last?.rows ?? []).map((r: any) => (Array.isArray(r) ? r : columns.map((c) => r[c])).map((v: any) =>
    v instanceof Date ? v.toISOString().replace('T', ' ').replace(/\.000Z$/, 'Z') : v !== null && typeof v === 'object' && !(v instanceof Uint8Array) ? JSON.stringify(v) : cell(v)));
  return { columns, rows, ms: performance.now() - t0, statements: results.length };
}

// Cards for the Data modeling studio — demos/diagrams/data-modeling-cards.js,
// verbatim, with types: the sample schema, the card geometry, and the HTML trees
// a table, a group zone and a note paint. Pure data in, pure data out — no DOM
// except text measuring — so the React, Vue, Angular and Qwik versions (each
// with an identical copy next to its demo file) render the very same cards.
//
// A table card keeps the diagram kit's class contract (.axk-entity / .axk-row /
// .axk-col / .axk-ty) so the kit's live join guidance (bindJoinGuidance) can
// tint its rows while a foreign key is being dragged. It is the page's own tree
// because the kit card has no UQ / NN switches, no footer and no row grips.
import type { Table, Column, Rel, Group, Note, Schema } from './data-modeling-sql';

/** A node of the renderer's structured, sanitised html layer. */
export interface HtmlTree { tag: string; className?: string; text?: string; attrs?: Record<string, string>; children?: HtmlTree[] }

/** Card geometry. Every row is exactly ROW px tall, so a port can sit on its centre. */
export const GEO = { HEAD: 36, ROW: 24, FOOT: 28, MIN_W: 240, MAX_W: 400 };
/** Node-local y of column `i`'s centre (the +1 is the card's top border). */
export const rowY = (i: number) => 1 + GEO.HEAD + i * GEO.ROW + GEO.ROW / 2;
export const tableHeight = (t: { columns: unknown[] }) => 2 + GEO.HEAD + t.columns.length * GEO.ROW + GEO.FOOT;

/** Zone frame: header band + padding around the tables it holds. */
export const ZONE = { HEAD: 48, PAD: 18, HIDDEN_H: 42, EMPTY_W: 340, EMPTY_H: 220 };
export const ZONE_COLORS = ['blue', 'green', 'amber', 'violet', 'rose', 'teal'];
export const ZONE_HEX: Record<string, string> = { blue: '#3b82f6', green: '#10b981', amber: '#f59e0b', violet: '#8b5cf6', rose: '#f43f5e', teal: '#14b8a6' };

export const NOTE_W = 290;

// The monospace stack the card CSS uses — measured with the same fonts.
export const MONO = 'Menlo, Consolas, "DejaVu Sans Mono", monospace';
let ctx2d: CanvasRenderingContext2D | null | undefined;
const measure = (text: string, font: string) => {
  if (ctx2d === undefined) { try { ctx2d = document.createElement('canvas').getContext('2d'); } catch { ctx2d = null; } }
  if (!ctx2d) return String(text).length * 7.2;
  ctx2d.font = font;
  return ctx2d.measureText(String(text)).width;
};

/** Card width from its content: the longest name + type + the switches. */
export function tableWidth(t: Table): number {
  let w = 12 + 8 + 8 + measure(t.name, `600 13px ${MONO}`) + 8 + 18 + 10;
  for (const c of t.columns) {
    // padding 10+8 · key 16 · gaps · name · type · UQ 24 · NN 24 · delete 14 · borders
    w = Math.max(w, 18 + 16 + 6 + measure(c.name, `${c.pk ? 600 : 400} 12px ${MONO}`) + 10 + measure(c.type, `11px ${MONO}`) + 8 + 24 + 3 + 24 + 4 + 14 + 2);
  }
  return Math.min(GEO.MAX_W, Math.max(GEO.MIN_W, Math.ceil(w + 6)));
}
export const tableSize = (t: Table) => ({ w: tableWidth(t), h: tableHeight(t) });

// ---------------------------------------------------------------------------
// The sample: a small online shop, in three groups
// ---------------------------------------------------------------------------

let seq = 0;
const C = (name: string, type: string, f = ''): Column => ({ id: `c${++seq}`, name, type, pk: f.includes('pk'), uq: f.includes('uq'), nn: f.includes('nn') || f.includes('pk') });

/** The schema the page opens on. Fresh objects every call (reset = a new copy). */
export function sampleSchema(): Schema {
  seq = 0;
  const tables: Table[] = [
    { id: 'customers', name: 'customers', x: 0, y: 0, columns: [C('id', 'uuid', 'pk'), C('email', 'varchar(255)', 'uq nn'), C('full_name', 'varchar(120)', 'nn'), C('phone', 'varchar(32)'), C('created_at', 'timestamp', 'nn')] },
    { id: 'addresses', name: 'addresses', x: 0, y: 0, columns: [C('id', 'uuid', 'pk'), C('customer_id', 'uuid', 'nn'), C('line1', 'varchar(200)', 'nn'), C('city', 'varchar(80)', 'nn'), C('country', 'char(2)', 'nn'), C('postal_code', 'varchar(16)')] },
    { id: 'orders', name: 'orders', x: 0, y: 0, columns: [C('id', 'uuid', 'pk'), C('customer_id', 'uuid', 'nn'), C('address_id', 'uuid'), C('status', 'varchar(20)', 'nn'), C('total', 'decimal(10,2)', 'nn'), C('placed_at', 'timestamp', 'nn')] },
    { id: 'order_items', name: 'order_items', x: 0, y: 0, columns: [C('id', 'serial', 'pk'), C('order_id', 'uuid', 'nn'), C('product_id', 'uuid', 'nn'), C('quantity', 'integer', 'nn'), C('unit_price', 'decimal(10,2)', 'nn')] },
    { id: 'payments', name: 'payments', x: 0, y: 0, columns: [C('id', 'uuid', 'pk'), C('order_id', 'uuid', 'uq nn'), C('provider', 'varchar(30)', 'nn'), C('amount', 'decimal(10,2)', 'nn'), C('paid_at', 'timestamp')] },
    { id: 'categories', name: 'categories', x: 0, y: 0, columns: [C('id', 'serial', 'pk'), C('name', 'varchar(80)', 'nn'), C('slug', 'varchar(80)', 'uq nn')] },
    { id: 'products', name: 'products', x: 0, y: 0, columns: [C('id', 'uuid', 'pk'), C('category_id', 'integer'), C('sku', 'varchar(32)', 'uq nn'), C('name', 'varchar(160)', 'nn'), C('price', 'decimal(10,2)', 'nn'), C('in_stock', 'boolean', 'nn'), C('created_at', 'timestamp', 'nn')] },
  ];
  const col = (t: string, n: string) => tables.find((x) => x.id === t)!.columns.find((c) => c.name === n)!.id;
  let r = 0;
  const R = (ft: string, fc: string, tt: string, tc: string, onDelete = 'NO ACTION', card = 'N:1'): Rel => ({ id: `r${++r}`, from: { t: ft, c: col(ft, fc) }, to: { t: tt, c: col(tt, tc) }, card, onDelete });
  const rels = [
    R('addresses', 'customer_id', 'customers', 'id', 'CASCADE'),
    R('orders', 'customer_id', 'customers', 'id', 'RESTRICT'),
    R('orders', 'address_id', 'addresses', 'id', 'SET NULL'),
    R('order_items', 'order_id', 'orders', 'id', 'CASCADE'),
    R('order_items', 'product_id', 'products', 'id', 'RESTRICT'),
    R('payments', 'order_id', 'orders', 'id', 'CASCADE', '1:1'),
    R('products', 'category_id', 'categories', 'id', 'SET NULL'),
  ];
  // Three columns of tables, one group each; the note fills the gap under Customers.
  const byId = new Map(tables.map((t) => [t.id, t]));
  const columns = [['customers', 'addresses'], ['orders', 'order_items', 'payments'], ['categories', 'products']];
  let x = 0;
  const groups: Group[] = [];
  const names = ['Customers', 'Orders', 'Catalog'], colors = ['blue', 'amber', 'green'];
  columns.forEach((ids, k) => {
    const w = Math.max(...ids.map((id) => tableWidth(byId.get(id)!)));
    let y = ZONE.HEAD;
    for (const id of ids) { const t = byId.get(id)!; t.x = x + ZONE.PAD; t.y = y; y += tableHeight(t) + 24; }
    groups.push({ id: `g${k + 1}`, name: names[k], color: colors[k], x, y: 0, w: w + 2 * ZONE.PAD, h: y - 24 + ZONE.PAD, hidden: false });
    x += w + 2 * ZONE.PAD + 76;
  });
  const cust = groups[0];
  const notes: Note[] = [{
    id: 'n1', x: cust.x, y: cust.h + 36, w: Math.max(NOTE_W, cust.w),
    text: 'Start here\nThis online shop is drawn as tables you can edit; the SQL on the right follows every change.\n· T, G and N add a table, a group and a note\n· Click any name or type to change it — UQ, NN and the key are switches\n· Pull the blue grip at a row\'s edge onto a column of another table to add a foreign key\n· ▶ Run SQL builds it all in a real database inside your browser',
  }];
  return { tables, rels, groups, notes };
}

// ---------------------------------------------------------------------------
// HTML trees (the renderer's structured, sanitised html layer)
// ---------------------------------------------------------------------------

/** `text` split around every case-insensitive hit of `q`, hits wrapped in <b class="dm-hl">. */
export function highlight(text: string, q: string): HtmlTree[] {
  const s = String(text);
  if (!q) return [{ tag: 'span', text: s }];
  const out: HtmlTree[] = [];
  const lower = s.toLowerCase();
  let i = 0;
  for (;;) {
    const j = lower.indexOf(q, i);
    if (j < 0) break;
    if (j > i) out.push({ tag: 'span', text: s.slice(i, j) });
    out.push({ tag: 'b', className: 'dm-hl', text: s.slice(j, j + q.length) });
    i = j + q.length;
  }
  if (i < s.length || !out.length) out.push({ tag: 'span', text: s.slice(i) });
  return out;
}

/**
 * A table card. `view`: { fk: Set<colId> (referencing columns), q: search
 * text (lower-case), color: the group's colour name or '' }.
 */
export function tableContent(t: Table, view: { fk: Set<string>; q: string; color: string }): HtmlTree {
  const q = view.q || '';
  const tableHit = !!q && t.name.toLowerCase().includes(q);
  const colHit = (c: Column) => !!q && (c.name.toLowerCase().includes(q) || String(c.type).toLowerCase().includes(q));
  const anyHit = tableHit || t.columns.some(colHit);
  const pkCount = t.columns.filter((c) => c.pk).length;
  const rows = t.columns.map((c): HtmlTree => {
    const fk = view.fk.has(c.id);
    const implied = c.pk && pkCount === 1;   // a single-column key is unique and not null by definition
    return {
      tag: 'div',
      className: `axk-row dm-row dm-c-${c.id}${c.pk ? ' dm-pk' : ''}${fk ? ' dm-fk' : ''}${colHit(c) ? ' dm-match' : ''}`,
      children: [
        { tag: 'span', className: 'dm-key', attrs: { title: c.pk ? 'Primary key — click to unset' : pkCount ? 'Click to add this column to the primary key' : 'Click to make this the primary key' } },
        { tag: 'span', className: 'axk-col dm-cname', children: highlight(c.name, q) },
        { tag: 'span', className: 'axk-ty dm-ctype', attrs: { title: 'Change the type' }, children: highlight(c.type, q) },
        { tag: 'span', className: `dm-badge dm-uq${c.uq || implied ? ' on' : ''}${implied ? ' implied' : ''}`, text: 'UQ', attrs: { title: implied ? 'Unique — implied by the primary key' : c.uq ? 'Unique — click to allow duplicates' : 'Click to make values unique' } },
        { tag: 'span', className: `dm-badge dm-nn${c.nn || implied ? ' on' : ''}${implied ? ' implied' : ''}`, text: 'NN', attrs: { title: implied ? 'Not null — implied by the primary key' : c.nn ? 'Not null — click to allow NULL' : 'Click to forbid NULL' } },
        { tag: 'span', className: 'dm-cdel', attrs: { title: 'Delete column' } },
      ],
    };
  });
  return {
    tag: 'div',
    className: `axk-entity dm-card${q ? (anyHit ? ' dm-hit' : ' dm-dim') : ''}`,
    children: [
      { tag: 'div', className: 'axk-entity-head dm-head', children: [
        { tag: 'span', className: `dm-tdot${view.color ? ` dm-zc-${view.color}` : ''}` },
        { tag: 'span', className: 'dm-tname', attrs: { title: 'Rename the table' }, children: highlight(t.name, q) },
        { tag: 'span', className: 'dm-tdel', attrs: { title: 'Delete table' } },
      ] },
      { tag: 'div', className: 'axk-entity-body dm-body', children: rows },
      { tag: 'div', className: 'dm-foot', children: [
        { tag: 'span', className: 'dm-count', text: `${t.columns.length} column${t.columns.length === 1 ? '' : 's'}` },
        { tag: 'span', className: 'dm-add', text: '+ Add column' },
      ] },
    ],
  };
}

/** A group zone: coloured dot, title, table count, the ⋯ menu and the hide/show eye. */
export function zoneContent(g: Group, view: { count: number; match: boolean }): HtmlTree {
  const n = view.count;
  const label = g.hidden ? `${n} table${n === 1 ? '' : 's'} hidden` : n ? `${n} table${n === 1 ? '' : 's'}` : 'drop tables here';
  return {
    tag: 'div',
    className: `dm-zone dm-zc-${g.color}${g.hidden ? ' dm-zone-hidden' : ''}${view.match ? ' dm-zone-match' : ''}`,
    children: [
      { tag: 'div', className: 'dm-zhead', children: [
        { tag: 'span', className: 'dm-zdot' },
        { tag: 'span', className: 'dm-ztitle', attrs: { title: 'Rename the group' }, text: g.name },
        { tag: 'span', className: 'dm-zcount', text: label },
        { tag: 'span', className: 'dm-zsp' },
        { tag: 'span', className: 'dm-zbtn dm-zmenu', attrs: { title: 'Group menu' } },
        { tag: 'span', className: `dm-zbtn dm-zeye${g.hidden ? ' off' : ''}`, attrs: { title: g.hidden ? 'Show its tables' : 'Hide its tables' } },
      ] },
    ],
  };
}

/** A sticky note: the first line is its title. */
export function noteContent(n: Note): HtmlTree {
  const [title, ...rest] = String(n.text || '').split('\n');
  return {
    tag: 'div',
    className: 'dm-note',
    children: [
      { tag: 'div', className: 'dm-nhead', children: [
        { tag: 'span', className: 'dm-ntitle', text: title || 'Note' },
        { tag: 'span', className: 'dm-ndel', attrs: { title: 'Delete note' } },
      ] },
      { tag: 'div', className: 'dm-ntext', text: rest.join('\n') },
    ],
  };
}

/** Port ids: `<table>::<column>::l|r` on a table, `<group>::zone::l|r` on a hidden group. */
export const portId = (owner: string, part: string, side: string) => `${owner}::${part}::${side}`;
export function parsePortId(pid: string | null | undefined): { t: string; c: string; side: string } | null {
  const m = /^(.+?)::(.+?)::([lr])$/.exec(pid || '');
  return m ? { t: m[1], c: m[2], side: m[3] } : null;
}
